function managerPlan(teamId,opponentHand='우투'){const staff=officeAI(teamId).manager,style=staff.style||'분석형';const ps=state.players.filter(p=>p.teamId===teamId&&p.level==='1군'&&!p.draftPending&&!(p.profile?.injury?.days>0)&&(!p.nationalDutyUntil||seasonDate(state.day).toISOString().slice(0,10)>p.nationalDutyUntil));const recent=(state.gameResults||[]).filter(g=>g.year==null||Number(g.year)===Number(state.year)).slice(-70);const recentBat=p=>{let ab=0,h=0,games=0;for(let i=recent.length-1;i>=0&&games<10;i--){const g=recent[i];const line=[...(g.awayBatters||[]),...(g.homeBatters||[])].find(x=>x.id===p.id);if(!line)continue;games++;ab+=line.atBats||0;h+=line.hits||0}return {ab,h,games}};const form=p=>{const last=recentBat(p);const recentWeight=Math.min(1,last.ab/25);const recentBonus=last.ab>=12?Math.max(-16,Math.min(16,(last.h/last.ab-.260)*90*recentWeight)):0;const ab=p.atBats||0,avg=ab?p.hits/ab:.25,weight=Math.min(1,ab/65);return (p.overall||50)*.45+batterForm(p,'contact')*.4+batterForm(p,'power')*.3+(avg-.25)*120*weight+recentBonus+(p.homeRuns||0)*.4-(playerBaseball(p).fatigue||0)*.3+((p.atBats||0)>=35&&avg<.220?-9:0)};const hitters=ps.filter(p=>p.position!=='P').sort((a,b)=>form(b)-form(a)||a.id-b.id).slice(0,16);const pitchers=ps.filter(p=>p.position==='P').sort((a,b)=>(b.overall||0)-(a.overall||0)||a.id-b.id).slice(0,12);const starters=pitchers.slice(0,5),bullpen=pitchers.slice(5),roles=new Map();starters.forEach(p=>roles.set(p.id,'선발'));bullpen.forEach(p=>roles.set(p.id,'불펜'));const closer=bullpen.slice().sort((a,b)=>(b.overall||0)-(a.overall||0)||a.id-b.id)[0];if(closer)roles.set(closer.id,'마무리');const philosophy=managerPhilosophy(staff);const lineupScore=p=>form(p)+(philosophy==='세이버메트릭스'?managerialBattingValue(p,philosophy)*.18:0);const lineup=chooseBattingNine(hitters,opponentHand,lineupScore,style,philosophy);return {first:[...pitchers,...hitters],chosenIds:new Set([...pitchers,...hitters].map(p=>p.id)),rotation:starters,starters,bullpen,roles,lineup,lineupPositions:lineup.assignedPositions,score:form,style}}
