function managerSubstitutions(club,inning,lead,r){if(inning<6||!club.batters.length||club.league==='amateur')return;const office=officeAI(club.teamId),staff=(club.league==='minor'?office.minorManager:office.manager)||office.manager,aggressive=staff.style==='공격형'||staff.style==='승부형';const bench=club.plan.first.filter(p=>p.position!=='P'&&!club.batters.some(x=>x.id===p.id)&&!club.substituted?.has(p.id));if(!bench.length)return;club.substituted=club.substituted||new Set();const maxChanges=aggressive?3:2;if(club.substitutions.length>=maxChanges)return;const candidates=club.batters.map((p,i)=>({p,i,fatigue:playerBaseball(p).fatigue||0,score:club.plan.score(p)})).sort((a,b)=>(b.fatigue-a.fatigue)*.65+(a.score-b.score)*.35);const weak=candidates[0];if(!weak)return;const positionOf=p=>{let id=p.id;for(let n=0;n<12;n++){const pos=club.plan.lineupPositions?.get(id);if(pos)return pos;const change=club.substitutions.find(x=>x.to===id);if(!change)break;id=change.from}return p.position};const slot=positionOf(weak.p);const eligible=bench.filter(p=>slot==='DH'||defensiveFit(p,slot)>=5);if(!eligible.length)return;const philosophy=managerPhilosophy(staff);const matchupHand=club.opponentStarterHand||null;const value=p=>club.plan.score(p)*.55+managerialBattingValue(p,philosophy)*.45+(matchupHand&&playerBaseball(p).batHand===(matchupHand==='좌투'?'우타':'좌타')?3:0);const next=eligible.sort((a,b)=>value(b)-value(a)||a.id-b.id)[0];const diff=value(next)-value(weak.p);if(!(weak.fatigue>=68||inning>=7&&diff>6||inning>=8&&lead<0&&diff>2))return;const idx=weak.i;club.batters[idx]=next;club.substituted.add(weak.p.id);club.substitutions.push({inning,from:weak.p.id,to:next.id,reason:weak.fatigue>=68?'피로 교체':lead<0?'대타 투입':'타순 조정'});next.games=(next.games||0)+1}
