function seasonDate(day){const start=state?.seasonStartDate||localTodayISO();const d=new Date(start+'T12:00:00');d.setDate(d.getDate()+day-1);return d}function seasonDateLabel(day){const d=seasonDate(day);return d.getFullYear()+'년 '+(d.getMonth()+1)+'월 '+d.getDate()+'일 ('+['일','월','화','수','목','금','토'][d.getDay()]+')'}function scheduledPairs(day){const d=seasonDate(day),dow=d.getDay();if(d.getMonth()<2||(d.getMonth()===2&&d.getDate()<20))return [];if(dow===1||state.teams.every(t=>(t.wins||0)+(t.losses||0)+(t.draws||0)>=144))return [];const start=new Date(state.year+'-03-20T12:00:00'),firstDow=start.getDay(),firstMondayOffset=(8-firstDow)%7,seasonDay=Math.floor((d-start)/86400000)+1,week=seasonDay-1<firstMondayOffset?0:Math.floor((seasonDay-1-firstMondayOffset)/7)+1;const series=week===0?0:week*2-1+(dow>=5?1:0);const ids=state.teams.map(t=>t.id),n=ids.length,round=series%(n-1),cycle=Math.floor(series/(n-1));const rotating=ids.slice(1);for(let k=0;k<round;k++)rotating.unshift(rotating.pop());const order=[ids[0],...rotating];return Array.from({length:n/2},(_,i)=>{const x=order[i],y=order[n-1-i],reverse=(round+i+cycle)%2===1;return reverse?[y,x]:[x,y]}).filter(([a,b])=>[a,b].every(id=>{const t=state.teams[id];return (t.wins||0)+(t.losses||0)+(t.draws||0)<144}))}

