function officeAI(teamId){const t=state.teams[teamId];if(!t.staff)t.staff={};for(const [key,label] of [['president','구단 사장'],['gm','단장'],['manager','감독'],['pitchCoach','투수코치'],['batCoach','타격코치'],['scout','스카우트'],['trainer','트레이너'],['minorManager','2군 감독'],['minorPitchCoach','2군 투수코치'],['minorBatCoach','2군 타격코치'],['minorTrainer','2군 트레이너']]){if(!t.staff[key])t.staff[key]={name:'구단 '+label,skill:55+((teamId*13+key.length*7)%35)};const x=t.staff[key];if(!x.style)x.style=['육성형','분석형','승부형','안정형','공격형'][(teamId+key.length)%5];if(!Number.isFinite(x.hiredYear))x.hiredYear=state.year;if(!Number.isFinite(x.contractEndYear))x.contractEndYear=x.hiredYear+(key==='president'||key==='gm'?3:key==='manager'?2:1);if(!Number.isFinite(x.salary)||x.salary<=0)x.salary=Math.round((key==='president'?250000000:key==='gm'?190000000:key==='manager'?150000000:60000000)+(Number(x.skill)||60)*(key==='president'?4000000:key==='gm'?3200000:key==='manager'?4500000:1200000));if(/^구단 (사장|단장|감독|투수코치|타격코치|스카우트|트레이너|2군 감독|2군 투수코치|2군 타격코치|2군 트레이너)$/.test(x.name)){const family=['김','이','박','최','정','강','윤','임','한','오'],given=['성호','준영','민수','태현','정우','재민','동혁','승현','영준','상훈'];x.name=family[(teamId*7+key.length)%family.length]+given[(teamId*3+key.length*5)%given.length];x.generatedStaffName=true}}return t.staff}
