function managerRatings(teamId,league='major'){if(league==='amateur')return {tactics:60,pitching:60,development:60,baserunning:60,leadership:60};const staff=officeAI(teamId),m=(league==='minor'?staff.minorManager:staff.manager)||staff.manager;const seed=String(m.name||'감독').split('').reduce((n,c)=>n+c.charCodeAt(0),teamId*701+(m.hiredYear||0)*13);m.ratings=m.ratings||{};for(const [key,offset] of [['tactics',11],['pitching',29],['development',47],['baserunning',61],['leadership',83]]){if(!Number.isFinite(m.ratings[key]))m.ratings[key]=Math.max(35,Math.min(95,Math.round((Number(m.skill)||60)*.55+25+((seed+offset*17)%41)-20)))}return m.ratings}
function retiredStaffCandidate(teamId,role){const occupied=new Set(state.teams.flatMap(t=>Object.values(t.staff||{}).map(x=>x?.formerPlayerId).filter(Boolean)));for(const x of staffMarket())if(x.formerPlayerId)occupied.add(x.formerPlayerId);const pool=(state.retiredPlayers||[]).filter(x=>state.year-x.year>=1&&!occupied.has(x.id)).map(x=>state.players.find(p=>p.id===x.id)).filter(p=>p&&(role==='manager'||(role.includes('Pitch')?p.position==='P':p.position!=='P')));if(!pool.length)return null;pool.sort((a,b)=>b.overall-a.overall);const p=pool[0];return {name:p.name,formerPlayerId:p.id,skill:Math.max(45,Math.min(90,p.overall||60)),style:['육성형','분석형','승부형','안정형','공격형'][p.id%5],hiredYear:state.year}}
function hireRetiredCoaches(){for(const t of state.teams){const staff=officeAI(t.id);for(const role of ['pitchCoach','batCoach','minorPitchCoach','minorBatCoach']){const current=staff[role];if((current.contractEndYear||state.year)>state.year)continue;const roll=rng((state.year*15427+t.id*313+role.length*77)>>>0)();if(roll>.18)continue;const candidate=retiredStaffCandidate(t.id,role);if(!candidate)continue;candidate.contractEndYear=state.year+2;candidate.salary=Math.round(55000000+candidate.skill*1200000);staff[role]=candidate;clubNotice('코치 선임',t.name+' 은퇴 선수 출신 코치 선임',candidate.name+' 전 선수가 지도자로 복귀했습니다.',[t.id],[candidate.formerPlayerId])}}}
function reviewManagerEmployment(){const now=seasonDate(state.day),month=now.getMonth()+1;if(month<5||month>9||state.day%21!==0)return;for(const t of state.teams){const games=(t.wins||0)+(t.losses||0);if(games<45)continue;const staff=officeAI(t.id),m=staff.manager,ratings=managerRatings(t.id),rate=(t.wins||0)/games,gm=staff.gm,expectation=Math.max(.35,Math.min(.57,.43+((Number(gm.skill)||60)-60)*.001));if(rate>=expectation-.12||m.hiredYear===state.year||m.dismissedReviewYear===state.year)continue;const chance=Math.min(.8,.12+(expectation-rate)*1.8+(games>=90?.12:0));const roll=rng(((state.day*179)+(t.id*811)+(state.year*19))>>>0)();if(roll>=chance)continue;const oldName=m.name;releaseStaffToMarket(m,'manager',t.id,'성적 부진 경질');const alumni=recruitMarketStaff(t.id,'manager',50)||retiredStaffCandidate(t.id,'manager');staff.manager=alumni||{name:t.city+' '+['김','이','박','최','정','한','오','윤','강','임'][(state.day+t.id)%10]+['태현','성준','재민','영수','준혁','민석','동현','승호'][(state.year+t.id)%8]+' 감독',skill:Math.max(45,Math.min(90,(Number(m.skill)||60)+Math.round((roll-.3)*18))),style:['분석형','공격형','안정형','육성형','승부형'][(state.day+t.id)%5],hiredYear:state.year,dismissedReviewYear:state.year};staff.manager.contractEndYear=state.year+2;staff.manager.salary=Math.round(160000000+(Number(staff.manager.skill)||60)*2500000);managerRatings(t.id);t.managerHistory=t.managerHistory||[];t.managerHistory.push({year:state.year,day:state.day,former:oldName,replacement:staff.manager.name,wins:t.wins,losses:t.losses});clubNotice('감독 교체',t.city+' '+t.name+' 감독 경질 · 후임 선임','단장이 시즌 '+games+'경기 '+(t.wins||0)+'승 '+(t.losses||0)+'패를 평가했습니다. 기대 승률 '+(expectation*100).toFixed(1)+'%에 미치지 못해 '+oldName+' 감독과 결별하고 '+staff.manager.name+' 감독을 선임했습니다. '+staffContractSummary(staff.manager),[t.id],[])}}
function publishMajorFaArticle(p,from,to,contract){
 if(!contract||!state||p.foreignPlayer)return;
 const total=Number(contract.totalValue)||0,years=Number(contract.years)||1;
 // Report substantial contracts or major moves, without flooding the news.
 if(total<1000000000&&!(from!==to&&total>=500000000))return;
 const key=[contract.signedYear,p.id,from,to,total].join(':');
 state.majorFaArticleKeys=state.majorFaArticleKeys||{};
 if(state.majorFaArticleKeys[key])return;
 const oldClub=state.teams.find(t=>String(t.id)===String(from));
 const newClub=state.teams.find(t=>String(t.id)===String(to));
 const moved=String(from)!==String(to);
 const headline='[FA 특집] '+p.name+', '+(moved?(newClub?.name||'새 구단')+' 이적':'원소속팀 잔류')+'… '+years+'년 총액 '+money(total);
 const article=p.name+' 선수가 FA 시장에서 '+years+'년 총액 '+money(total)+' 규모의 계약을 체결했다. '+(moved?(oldClub?.name||'전 소속팀')+'에서 '+(newClub?.name||'새 구단')+'(으)로 유니폼을 바꾸며 새로운 도전에 나선다.':'원소속 구단과 재계약하며 동행을 이어간다.')+' 연봉 '+money(Number(contract.annualSalary)||0)+', 계약금 '+money(Number(contract.signingBonus)||0)+'이 포함된 계약으로, 구단의 향후 전력 구성에도 영향을 줄 전망이다.';
 clubNotice('FA 특집',headline,article,[from,to],[p.id]);
 state.majorFaArticleKeys[key]=true;
}
