  if(!pick)continue;
  const actual=state.teams.find(t=>String(t.id)===String(pick.teamId));
  const expected=state.teams.find(t=>String(t.id)===String(prediction.favoriteId));
  const matched=String(pick.teamId)===String(prediction.favoriteId);
  const title='[드래프트 결과] '+pick.name+', '+(actual?.name||'구단')+' 지명… '+(matched?'유력 전망 적중':'당초 예상과 다른 선택');
