function frontOfficeProjectMonth(t,key){const f=t.finance;const [year,month]=key.split('-').map(Number);if(f.lastProjectMonth===key)return;f.lastProjectMonth=key;if(f.project&&Number(f.project.untilYear)*12+Number(f.project.untilMonth)>=year*12+month)return;f.project=null;const reserve=10000000000,spare=Math.max(0,t.budget-reserve);if(spare<1000000000)return;const roster=state.players.filter(p=>p.teamId===t.id&&!p.retired&&p.level!=='방출');const young=roster.filter(p=>(Number(p.age)||30)<=25).length;const games=(Number(t.wins)||0)+(Number(t.losses)||0);const pct=games?(Number(t.wins)||0)/games:.5;const priorities=pct<.44?['youth','scout','pitch','bat','marketing','medical']:pct>.56?['medical','pitch','bat','scout','youth','marketing']:['pitch','bat','youth','medical','marketing','scout'];if(young>18)priorities.unshift('youth');const id=priorities[(year*7+month+t.id)%Math.min(3,priorities.length)],project=FRONT_PROJECTS.find(x=>x.id===id);const budget=Math.min(Math.floor(spare*.12),6000000000),cost=budget>=6000000000?6000000000:budget>=3000000000?3000000000:1000000000;if(cost>spare||!financeEntry(t.id,-cost,'특별 투자',project.name))return;const level=cost>=6000000000?3:cost>=3000000000?2:1,expiry=year*12+month+project.months-1;f.project={id,name:project.name,level,cost,startedYear:year,startedMonth:month,untilYear:Math.floor((expiry-1)/12),untilMonth:(expiry-1)%12+1};if(t.id===state.teamId)clubNotice('프런트 특별 투자',project.name+' 추진','AI 프런트가 '+Math.round(cost/100000000)+'억원을 집행했습니다. '+project.months+'개월간 효과가 적용됩니다.',[t.id],[])}
function frontOfficeFacilityMonth(t,key){const f=t.finance,fac=f.facilities||(f.facilities={training:0,scouting:0,medical:0,stadium:0});const levels=['training','scouting','medical','stadium'];const labels={training:'훈련·육성시설',scouting:'스카우트 분석실',medical:'의료·재활센터',stadium:'구장·팬 시설'};if(f.lastFacilityMonth===key)return;f.lastFacilityMonth=key;const reserve=10000000000,available=Math.max(0,t.budget-reserve);if(available<2000000000)return;const priority=levels.slice().sort((a,b)=>(Number(fac[a])||0)-(Number(fac[b])||0)||levels.indexOf(a)-levels.indexOf(b));for(const type of priority){const level=Math.max(0,Math.min(5,Number(fac[type])||0));if(level>=5)continue;const cost=(20+level*15)*100000000;if(cost>available*.35||cost>t.budget-reserve)continue;if(financeEntry(t.id,-cost,'시설 투자',labels[type]+' '+(level+1)+'단계 증설')){fac[type]=level+1;if(t.id===state.teamId)clubNotice('프런트 투자',labels[type]+' 증설',labels[type]+'을 '+(level+1)+'단계로 확충했습니다. 투자금 '+Math.round(cost/100000000)+'억원은 구단 예산에서 집행했습니다.',[t.id],[])}break}}
function frontOfficeFinancePanel(t){const f=t.finance||{},fac=f.facilities||{},names=[['training','훈련·육성','선수 성장'],['scouting','스카우트','선수 발굴'],['medical','의료·재활','부상 예방'],['stadium','구장·팬','입장 수익']],ledger=Array.isArray(f.ledger)?f.ledger:[],recent=ledger.slice(-12).reverse(),amount=n=>(Math.abs(Number(n)||0)/100000000).toFixed(1)+'억',levels=names.map(([k,label,desc])=>{const level=Math.max(0,Math.min(5,Number(fac[k])||0));return '<div class="fo-facility"><div class="fo-facility-head"><strong>'+label+'</strong><span>'+level+' / 5</span></div><small>'+desc+'</small><div class="fo-progress"><i style="width:'+(level*20)+'%"></i></div></div>'}).join('');const rows=recent.map(x=>{const n=Number(x.amount)||0;return '<div class="fo-transaction"><div class="fo-transaction-info"><strong>'+esc(x.kind||'거래')+'</strong><small>'+esc(x.detail||'')+'</small></div><b class="'+(n>=0?'fo-plus':'fo-minus')+'">'+(n>=0?'+':'−')+amount(n)+'</b></div>'}).join('');return '<section class="dashboard-section fo-section"><div class="fo-heading"><span class="section-kicker">CLUB FINANCE</span><h2>구단 재정</h2></div><div class="fo-balance"><small>현재 보유 자금</small><strong>'+amount(t.budget)+'원</strong><span>AI 프런트 자동 예산 운영</span></div><div class="fo-heading"><h3>시설 투자 현황</h3><small>매월 자동 투자 · 최대 5단계</small></div><div class="fo-facilities">'+levels+'</div><div class="fo-heading"><h3>진행 중인 특별 투자</h3></div>'+(f.project&&frontProjectActive(t,f.project.id)?'<div class="fo-facility" style="margin-bottom:18px"><div class="fo-facility-head"><strong>'+esc(f.project.name)+'</strong><span>'+Math.round((Number(f.project.cost)||0)/100000000)+'억원</span></div><small>투자 단계 '+f.project.level+' · '+f.project.untilYear+'년 '+f.project.untilMonth+'월까지</small></div>':'<p class="profile-note">현재 진행 중인 특별 투자가 없습니다. 매월 재정 결산 시 자동 검토합니다.</p>')+'<details class="fo-ledger"><summary>최근 재정 거래 <span>'+recent.length+'건 보기</span></summary><div class="fo-transactions">'+(rows||'<p>재정 거래 기록이 없습니다.</p>')+'</div></details></section>'}
function financeMonth(){const d=seasonDate(state.day);if(d.getDate()!==1)return;const key=d.getFullYear()+'-'+(d.getMonth()+1);for(const t of state.teams){financeTeam(t.id);if(t.finance.lastMonth===key)continue;t.finance.lastMonth=key;const month=d.getMonth()+1,homeGames=(state.gameResults||[]).filter(g=>g.home===t.id&&g.day>=state.day-31&&g.day<state.day).length;const stadiumLevel=Math.min(5,Number(t.finance?.facilities?.stadium)||0);const gate=Math.round(homeGames*Math.round((t.fans||30000)*.5)*17000*(1+stadiumLevel*.035)*(frontProjectActive(t,'marketing')?1+t.finance.project.level*.03:1));const sponsors=Math.round((t.fans||30000)*12000);financeEntry(t.id,gate+sponsors,'구단 수입','입장 수입 및 월간 스폰서 수익');const salaries=state.players.filter(p=>p.teamId===t.id&&!p.retired&&p.level!=='방출').reduce((sum,p)=>sum+(Number(p.salary)||0),0);const coaches=Object.values(officeAI(t.id)).filter(Boolean).reduce((sum,member)=>sum+(Number(member.salary)||0)/12,0);const expenses=Math.round(salaries/12+coaches);const paid=Math.min(t.budget,expenses);financeEntry(t.id,-paid,'운영비','선수단 연봉 및 코치진 급여');frontOfficeFacilityMonth(t,key);frontOfficeProjectMonth(t,key);if(t.id===state.teamId)clubNotice('재정 보고',key+' 구단 재정 결산','수입 '+Math.round((gate+sponsors)/10000).toLocaleString()+'만원 · 지출 '+Math.round(paid/10000).toLocaleString()+'만원 · 잔액 '+Math.round(t.budget/100000000).toLocaleString()+'억원',[t.id],[])}}
