function amateurCareerSnapshot(p,kind,year,teamName){return {league:kind,year,team:teamName||'',games:Number(p.games)||0,atBats:Number(p.atBats)||0,hits:Number(p.hits)||0,homeRuns:Number(p.homeRuns)||0,inningsPitched:Number(p.inningsPitched??p.innings)||0,earnedRuns:Number(p.earnedRuns)||0,strikeouts:Number(p.pitchingStrikeouts??p.strikeouts)||0}}
