function clubNewsPanel(){const all=(state.clubNotices||[]).filter(n=>n.day===state.day&&Number(n.year)===Number(state.year)).slice().reverse(),items=[],seen=new Set(),groups=rosterNewsGroups();for(const n of all){if(['1군 콜업','1군 말소','부상자 명단','1군 등록'].includes(n.kind)){const key=n.year+':'+n.day+':'+n.teams?.[0];if(seen.has('roster'+key))continue;seen.add('roster'+key);const g=groups.get(key);if(!g)continue;const team=state.teams[g.teamId];const incoming=g.notices.filter(x=>['1군 콜업','1군 등록'].includes(x.kind)).length,outgoing=g.notices.length-incoming;if(incoming===0&&outgoing>=5)continue;items.push({id:'roster:'+key,kind:'선수단 변동',title:(team?.city||'')+' '+(team?.name||'구단')+' 1군 엔트리 변경 · 등록 '+incoming+'명 / 말소 '+outgoing+'명'});}else if(n.kind==='신인 드래프트'){const key='draft'+draftClassYear(n);if(seen.has(key))continue;seen.add(key);items.push({...n,title:draftClassYear(n)+'시즌 신인 드래프트 결과 발표 · 10개 구단 지명 완료'})}else items.push(n.kind==='시즌 시상'?{...n,title:awardNoticeTitle(n)}:n);if(items.length>=35)break}return '<section class="dashboard-section"><div class="section-title"><div><span class="section-kicker">ALL CLUBS</span><h2>오늘의 전 구단 소식</h2></div></div><div class="club-headline-list">'+(items.length?items.map(n=>'<button type="button" class="club-headline" data-club-notice="'+n.id+'"><span class="club-headline-kind">'+esc(n.kind)+'</span><span class="club-headline-title">'+esc(n.title)+'</span><span aria-hidden="true">›</span></button>').join(''):'<p>오늘 등록된 구단 소식이 없습니다.</p>')+'</div></section>'}
