function offseasonDay(){highSchoolBaseballDay();collegeBaseballDay();independentBaseballDay();financeMonth();calendarNotice();foreignRecruitmentDay();asianQuotaRecruitmentDay();activateDraftRookies();draftScoutReport();officeDraft();const d=seasonDate(state.day),month=d.getMonth()+1,day=d.getDate();if(awardsFinished()&&!state.postseasons?.[state.year]?.finished)postseasonDay();if(awardsFinished()&&state.postseasons?.[state.year]?.finished&&(month>11||(month===11&&day>=10))){runOffseasonContracts();annualSalaryNegotiations()}for(const t of state.teams)officeAI(t.id);coachDevelopmentDay(true);if(day===1){const label=month===11?'마무리 캠프':month===12?'재활·기초 체력 훈련':month===1?'동계 개인 훈련':month===2?'스프링캠프':month===3?'시범경기 대비 훈련':'포스트시즌·전력 분석';clubNotice('구단 일정',state.year+' '+month+'월 '+label,'감독·코치진이 선수별 훈련 및 휴식 계획을 자동 진행합니다. 구단주는 결과와 기사만 확인합니다.',[state.teamId],[])}if(month===2&&day===15)clubNotice('스프링캠프','스프링캠프 훈련 진행','감독과 코치진이 선발 로테이션과 타순을 점검하고 있습니다.',[state.teamId],[]);state.day++;if(state.events.length>150)state.events=state.events.slice(-150)}
let autoSeasonRunning=false,autoSeasonSpeed=1000,autoSeasonTimer=null,seasonStepBusy=false;function stopAutoSeason(){autoSeasonRunning=false;if(autoSeasonTimer!==null)clearTimeout(autoSeasonTimer);autoSeasonTimer=null}function scheduleAutoSeason(){if(!autoSeasonRunning||entryMode!=='game'||tab!=='home'){stopAutoSeason();return}autoSeasonTimer=setTimeout(async()=>{autoSeasonTimer=null;if(!autoSeasonRunning)return;const ok=await advanceSeason();if(ok&&autoSeasonRunning)scheduleAutoSeason();else if(!ok)stopAutoSeason()},autoSeasonSpeed)}function toggleAutoSeason(){if(autoSeasonRunning){stopAutoSeason();render();return}autoSeasonRunning=true;render();scheduleAutoSeason()}
async function advanceSeason(){if(seasonStepBusy)return false;seasonStepBusy=true;const perfStart=performance.now();let perfBackup=0,perfSim=0,perfSave=0;let advancePhase='시작';const btn=document.querySelector('#advance-day');if(btn)btn.disabled=true;let backup;try{advancePhase='백업 준비';// Past game results are append-only during a day; keep references to immutable
// historical entries and copy only the array container for rollback.
const priorResults=state.gameResults;
backup=structuredClone({...state,gameResults:undefined});
if(priorResults)backup.gameResults=priorResults.slice();
perfBackup=performance.now()-perfStart;advancePhase='시즌 일정 확인';ensureSeasonCalendar();monthlyOwnerReport();const currentDate=seasonDate(state.day);if(currentDate.getFullYear()>state.year){if(awardsFinished()&&state.postseasons?.[state.year]?.finished){if(!state.offseasonContractsDone?.[state.year])runOffseasonContracts();annualSalaryNegotiations();beginNextSeason()}else{throw new Error('이전 시즌 정규시즌 또는 포스트시즌이 완료되지 않았습니다. 기존 시즌 데이터를 보존하기 위해 새해 전환을 중단했습니다.')}}advancePhase='하루 시뮬레이션';if(awardsFinished()||seasonDate(state.day)<new Date(state.year+'-03-20T12:00:00')){offseasonDay();}else{simulateLeagueDay();}if(awardsFinished()&&state.postseasons?.[state.year]?.finished&&!state.history?.seasons?.[state.year]?.complete)saveSeasonSnapshot();if(state.day%30===0)validateSeasonIntegrity();const latest=(state.gameResults||[]).at(-1);if(latest)window.beNewsDay=latest.day;advancePhase='저장';perfSim=performance.now()-perfStart-perfBackup;await save();perfSave=performance.now()-perfStart-perfBackup-perfSim;window.beLastStepTiming={backup:perfBackup,simulation:perfSim,save:perfSave,total:performance.now()-perfStart};advancePhase='화면 갱신';if(entryMode==='game'&&tab==='home'){render();const nextButton=document.querySelector('#advance-day');if(nextButton)nextButton.disabled=true;}return true}catch(e){if(backup)state=backup;stopAutoSeason();render();alert('경기 진행 실패 ('+advancePhase+'): '+e.message);return false}finally{seasonStepBusy=false;const nextButton=document.querySelector('#advance-day');if(nextButton)nextButton.disabled=false}}

function newsStory(g){const a=state.teams[g.away],h=state.teams[g.home],draw=g.awayRuns===g.homeRuns,awayWin=g.awayRuns>g.homeRuns,w=awayWin?a:h,l=awayWin?h:a,margin=Math.abs(g.awayRuns-g.homeRuns),ai=g.awayInnings||[],hi=g.homeInnings||[];let ar=0,hr=0,decisive=null,peak=null,turns=[];for(let i=0;i<Math.max(ai.length,hi.length);i++){const x=Number(ai[i])||0,y=Number(hi[i])||0,previous=ar-hr;ar+=x;hr+=y;if(x+y){turns.push({inning:i+1,away:x,home:y,scoreA:ar,scoreH:hr});if(!peak||x+y>peak.away+peak.home)peak=turns[turns.length-1];if(previous!==0&&Math.sign(previous)!==Math.sign(ar-hr)&&ar!==hr)decisive=turns[turns.length-1]}}const title=draw?esc(a.name)+'·'+esc(h.name)+', 연장 끝 무승부':margin>=7?esc(w.name)+', '+margin+'점 차 압승…'+esc(l.name)+' 제압':margin===1?esc(w.name)+', '+esc(l.name)+'에 한 점 차 승리':esc(w.name)+', '+esc(l.name)+' 꺾고 '+margin+'점 차 승리';const summary=draw?esc(a.city+' '+a.name)+'와 '+esc(h.city+' '+h.name)+'가 '+g.awayRuns+'대 '+g.homeRuns+'로 승부를 가리지 못했다.':esc(w.city+' '+w.name)+'가 '+esc(l.city+' '+l.name)+'를 '+Math.max(g.awayRuns,g.homeRuns)+'대 '+Math.min(g.awayRuns,g.homeRuns)+'로 꺾었다.';return {title,summary,turns,decisive,peak,draw,margin}}
function gameArticle(g){const a=state.teams[g.away],h=state.teams[g.home],story=newsStory(g),ai=Array.isArray(g.awayInnings)?g.awayInnings:[],hi=Array.isArray(g.homeInnings)?g.homeInnings:[],n=Math.max(9,ai.length,hi.length),innings=Array.from({length:n},(_,i)=>i+1),winner=g.awayRuns>g.homeRuns?a:h,loser=winner===a?h:a;const boxTotal=(players,key)=>Array.isArray(players)?players.reduce((n,p)=>n+(Number(p[key])||0),0):'—';const steals=[...(g.awayBatters||[]),...(g.homeBatters||[])].filter(p=>(p.stolenBases||0)+(p.caughtStealing||0)>0).map(p=>esc(p.name)+' 도루 '+(p.stolenBases||0)+'회'+(p.caughtStealing?' · 도루실패 '+p.caughtStealing+'회':''));const stealsNote=steals.length?'<p class="article-note"><b>주루 기록</b> · '+steals.join(' / ')+'</p>':'';const row=(name,values,total,batters,errors)=>'<tr><th>'+esc(name)+'</th>'+innings.map((_,i)=>'<td>'+(values[i]===null?'-':values[i]??'-')+'</td>').join('')+'<td><b>'+total+'</b></td><td>'+boxTotal(batters,'hits')+'</td><td>'+(errors??'—')+'</td><td>'+boxTotal(batters,'walks')+'</td></tr>';const scored=story.turns||[],first=scored[0],peak=story.peak,decisive=story.decisive;const lead=story.draw?'승부는 마지막까지 팽팽했다. 두 팀은 '+g.awayRuns+'대 '+g.homeRuns+'로 경기를 마쳤다.':esc(winner.city+' '+winner.name)+'가 '+esc(loser.city+' '+loser.name)+'를 상대로 '+Math.max(g.awayRuns,g.homeRuns)+'대 '+Math.min(g.awayRuns,g.homeRuns)+' 승리를 거뒀다. '+(story.margin>=5?'큰 점수 차를 만들어낸 공격력이 승부를 갈랐다.':story.margin===1?'끝까지 승부를 알 수 없는 한 점 차 접전이었다.':'득점 기회를 살린 쪽이 승리를 가져갔다.');const paragraph1=first?'경기 초반부터 점수판이 움직였다. '+first.inning+'회 '+(first.away?esc(a.name)+'가 '+first.away+'점을 올렸고 ':'')+(first.home?esc(h.name)+'도 '+first.home+'점을 보탰다. ':'')+'이 이닝을 마친 시점 점수는 '+first.scoreA+'대 '+first.scoreH+'였다.':'경기 내내 양 팀은 득점을 올리지 못했다.';const paragraph2=decisive?'승부의 흐름이 달라진 시점은 '+decisive.inning+'회였다. 이 이닝에 '+(decisive.away?esc(a.name)+'가 '+decisive.away+'점을 기록했고 ':'')+(decisive.home?esc(h.name)+'가 '+decisive.home+'점을 추가하면서 ':'')+'누적 점수가 '+decisive.scoreA+'대 '+decisive.scoreH+'로 바뀌었다.':peak?'특히 '+peak.inning+'회에는 두 팀이 합쳐 '+(peak.away+peak.home)+'점을 올렸다. '+(peak.away?esc(a.name)+'의 '+peak.away+'득점':'')+(peak.away&&peak.home?'과 ':'')+(peak.home?esc(h.name)+'의 '+peak.home+'득점':'')+'이 집중된 이닝이었다.':'양 팀은 끝까지 팽팽한 투수전을 이어갔다.';const last=scored[scored.length-1],paragraph3=last&&last!==first?'이후에도 공방이 이어졌다. '+last.inning+'회에는 '+(last.away?esc(a.name)+'가 '+last.away+'점 ':'')+(last.home?esc(h.name)+'가 '+last.home+'점':'')+'을 올렸고, 최종 스코어는 '+g.awayRuns+'대 '+g.homeRuns+'로 확정됐다.':'경기 종료 후 전광판에는 '+g.awayRuns+'대 '+g.homeRuns+'가 남았다.';const pitchers=(id,records)=>'<div class="article-pitcher-team"><h5>'+esc(state.teams[id].city+' '+state.teams[id].name)+'</h5><ul>'+((records||[]).slice().sort((a,b)=>(a.entry??(a.role==='선발'?1:99))-(b.entry??(b.role==='선발'?1:99))).map(x=>{const p=state.players.find(p=>p.id===x.id);return p?'<li><button class="article-player-link" data-article-player="'+p.id+'">'+esc(p.name)+'</button><span>'+esc(x.role||'투수')+(x.role==='선발'?'':x.entry!=null?' · '+x.entry+'회 등판':'')+' · '+baseballIP(x.outs!=null?x.outs:Math.round((x.innings||0)*3))+'이닝 · '+(x.strikeouts??'—')+'K · '+(x.hits??'—')+'피안타 · '+(x.walks??'—')+'볼넷 · '+(x.earnedRuns??'—')+'자책'+(x.win?' · 승리':x.loss?' · 패전':x.save?' · 세이브':x.hold?' · 홀드':'')+'</span></li>':''}).filter(Boolean).join('')||'<li>기록 없음</li>')+'</ul></div>';const battingBox=(id,ps)=>{if(!Array.isArray(ps))return '<p class="article-note">이 경기는 타자별 기록이 저장되지 않았습니다.</p>';const ordered=ps.slice().sort((a,b)=>(a.battingOrder??99)-(b.battingOrder??99)||(a.subIn?1:0)-(b.subIn?1:0)||(a.subIn?.inning||0)-(b.subIn?.inning||0));const cells=p=>'<td>'+p.atBats+'</td><td>'+p.hits+'</td><td>'+(p.doubles??'—')+'</td><td>'+(p.triples??'—')+'</td><td>'+p.homeRuns+'</td><td>'+p.runsBattedIn+'</td><td>'+(p.runs??'—')+'</td><td>'+p.walks+'</td><td>'+p.stolenBases+'</td><td>'+(p.groundedIntoDoublePlays??'—')+'</td><td>'+(p.sacrificeFlies??'—')+'</td><td>'+(p.fieldingErrors??'—')+'</td>';return '<h5>'+esc(state.teams[id].city+' '+state.teams[id].name)+'</h5><p style="font-size:12px;color:#68829c;margin:5px 0 12px">타순별 선발 · 교체 선수 순서 / 교체 선수는 같은 타순 아래 표시</p><div class="scoreboard-scroll"><table class="scoreboard-table batting-box-table"><thead><tr><th>타순</th><th>선수 · 교체</th><th>포지션</th><th>타수</th><th>안타</th><th>2루타</th><th>3루타</th><th>홈런</th><th>타점</th><th>득점</th><th>볼넷</th><th>도루</th><th>병살타</th><th>희생플라이</th><th>실책</th></tr></thead><tbody>'+ordered.map((p,i)=>{const prior=ordered.find(x=>x.id===p.subIn?.from),following=ordered.find(x=>x.id===p.subOut?.to);const note=p.subIn?p.subIn.inning+'회 '+(prior?.name||'앞선 선수')+' 교체':p.subOut?p.subOut.inning+'회 → '+(following?.name||'교체 선수'):'선발';const first=i===0||ordered[i-1].battingOrder!==p.battingOrder;return '<tr style="'+(p.subIn?'background:#f1f6fc;':'')+(first?'border-top:2px solid #c9d8e9;':'')+'"><td style="font-weight:800;color:#234d79">'+(first?(p.battingOrder??'—'):'↳')+'</td><th style="text-align:left;min-width:112px;padding-left:'+(p.subIn?'20':'8')+'px"><button class="article-player-link" data-article-player="'+p.id+'">'+esc(p.name)+'</button><small style="display:block;font-size:10px;color:#637f9d;white-space:nowrap">'+esc(note)+'</small></th><td>'+esc(p.position||'—')+'</td>'+cells(p)+'</tr>'}).join('')+'</tbody></table></div>'};const topBatters=[...(g.awayBatters||[]),...(g.homeBatters||[])].filter(p=>p.runsBattedIn||p.homeRuns).sort((a,b)=>b.runsBattedIn-a.runsBattedIn||b.homeRuns-a.homeRuns).slice(0,4);const highlights=[...(g.awayBatters||[]).map(x=>({...x,club:g.away})),...(g.homeBatters||[]).map(x=>({...x,club:g.home}))].filter(x=>x.homeRuns||x.triples||x.doubles>=2||x.runsBattedIn>=2||x.hits>=3).sort((a,b)=>(b.homeRuns||0)-(a.homeRuns||0)||(b.triples||0)-(a.triples||0)||(b.runsBattedIn||0)-(a.runsBattedIn||0)||(b.doubles||0)-(a.doubles||0)||(b.hits||0)-(a.hits||0)).slice(0,4);const hitterStory=highlights.map(x=>{const lost=x.club===g.away?g.awayRuns<g.homeRuns:g.homeRuns<g.awayRuns;const extra=[x.doubles>0?x.doubles+'개의 2루타':null,x.triples>0?x.triples+'개의 3루타':null,x.homeRuns>0?x.homeRuns+'개의 홈런':null].filter(Boolean);return esc(state.teams[x.club].name+' '+x.name)+'은 '+(x.hits??0)+'안타'+(extra.length?'( '+extra.join(' · ')+' )':'')+' '+(x.runsBattedIn??0)+'타점을 기록했다.'+(lost&&x.homeRuns?' 홈런을 쳤지만 팀은 패했다.':'')}).join(' ');const starterStory=[{club:g.away,ps:g.awayPitchers||[]},{club:g.home,ps:g.homePitchers||[]}].map(t=>{const x=t.ps.find(p=>p.role==='선발')||t.ps[0],p=x&&state.players.find(p=>p.id===x.id);if(!p)return '';const outs=Number.isInteger(x.outs)?x.outs:Math.round((x.innings||0)*3);return esc(state.teams[t.club].name+' 선발 '+p.name)+'은 '+Math.floor(outs/3)+'과 '+outs%3+'/3이닝 '+(x.earnedRuns??'—')+'자책'+(x.strikeouts!=null?' '+x.strikeouts+'탈삼진':'')+(x.hits!=null?' '+x.hits+'피안타':'')+'를 기록했다.'}).filter(Boolean).join(' ');const playerStory='<p>'+hitterStory+'</p>'+(starterStory?'<p>'+starterStory+'</p>':'');return '<div class="news-article-body editorial-story"><div class="article-category">스포츠 <span>›</span> 야구 <span>›</span> 정규시즌</div><h1 class="editorial-headline">'+story.title+'</h1><p class="editorial-subtitle">'+lead+'</p><div class="editorial-meta"><strong>BASEBALL EMPIRE 스포츠팀</strong><span>'+seasonDateLabel(g.day)+' | 경기 종료</span></div><div class="editorial-hero"><div class="editorial-stadium"><div class="editorial-winner-logo">'+teamLogo(winner,true)+'<span>WINNER · '+esc(winner.city+' '+winner.name)+'</span></div><div class="editorial-hero-title">'+esc(a.name)+' <b>'+g.awayRuns+' : '+g.homeRuns+'</b> '+esc(h.name)+'</div></div><div class="editorial-caption">BASEBALL EMPIRE 경기 결과 · 게임 내 자동 생성된 그래픽</div></div><div class="editorial-copy"><p>'+lead+'</p><p>'+paragraph1+'</p><p>'+paragraph2+'</p><p>'+paragraph3+'</p>'+playerStory+'</div><div class="editorial-points"><h3>주요 포인트</h3><ul><li>최종 결과: '+esc(a.name)+' '+g.awayRuns+'대 '+g.homeRuns+' '+esc(h.name)+'</li>'+(peak?'<li>최다 득점 이닝: '+peak.inning+'회, 양 팀 합계 '+(peak.away+peak.home)+'점</li>':'')+(decisive?'<li>경기 흐름 변화: '+decisive.inning+'회, 누적 '+decisive.scoreA+'대 '+decisive.scoreH+'</li>':'')+'<li>경기장: '+esc(typeof g.venue==='string'&&g.venue.trim()&&!/^\\d+$/.test(g.venue.trim())?g.venue:ballpark(state.teams[g.home]))+' · '+esc(g.parkType||stadiumFactors(g.home).type)+'</li><li>경기 결과와 선수 기록은 저장된 시뮬레이션 데이터 기준</li></ul></div><h4>이닝별 점수</h4><div class="scoreboard-scroll"><table class="scoreboard-table"><thead><tr><th>구단</th>'+innings.map(i=>'<th>'+i+'</th>').join('')+'<th>R</th><th>H</th><th>E</th><th>BB</th></tr></thead><tbody>'+row(a.name,ai,g.awayRuns,g.awayBatters,g.awayErrors)+row(h.name,hi,g.homeRuns,g.homeBatters,g.homeErrors)+'</tbody></table></div>'+stealsNote+'<h4>양 팀 타자 기록</h4>'+battingBox(g.away,g.awayBatters)+battingBox(g.home,g.homeBatters)+'<h4>투수 주요 기록</h4><div class="article-pitchers">'+pitchers(g.away,g.awayPitchers)+pitchers(g.home,g.homePitchers)+'</div><p class="article-note">본 기사는 게임 내 실제 경기 결과를 바탕으로 자동 작성됐습니다.</p></div>'}
function displayedGameDay(){return Math.max(1,(Number(state.day)||1)-1)}
function recentScoreboards(){const all=state.gameResults||[],days=[...new Set(all.map(g=>g.day))].sort((a,b)=>b-a),day=days.includes(window.beNewsDay)?window.beNewsDay:days[0];if(day===undefined)return '<p class="roster-empty">아직 진행된 경기가 없습니다.</p>';const games=all.filter(g=>g.day===day).sort((a,b)=>(a.away===state.teamId||a.home===state.teamId?-1:0)-(b.away===state.teamId||b.home===state.teamId?-1:0));return '<div class="news-day-picker"><button type="button" id="news-prev-day" '+(days.indexOf(day)===days.length-1?'disabled':'')+'>‹ 이전 경기일</button><strong>'+seasonDateLabel(day)+' · '+games.length+'경기</strong><button type="button" id="news-next-day" '+(days.indexOf(day)===0?'disabled':'')+'>다음 경기일 ›</button></div><div class="news-headlines">'+games.map((g,i)=>'<button class="news-headline" data-game-day="'+g.day+'" data-game-away="'+g.away+'"><span class="news-headline-day">'+(g.away===state.teamId||g.home===state.teamId?'우리 팀':'리그')+'</span><strong>'+newsStory(g).title+'</strong><span class="news-headline-arrow">›</span></button>').join('')+'</div>'}
function openGameArticle(day,away){const g=(state.gameResults||[]).find(g=>g.day===day&&g.away===away);if(!g)return;document.querySelector('#game-news-overlay')?.remove();document.body.insertAdjacentHTML('beforeend','<div id="game-news-overlay" class="game-news-overlay"><article class="game-news-dialog" role="dialog" aria-modal="true" aria-label="경기 상세 기사"><header><div><small>BASEBALL EMPIRE SPORTS · '+seasonDateLabel(g.day)+'</small><h2>'+newsStory(g).title+'</h2></div><button id="close-game-news" type="button">× 닫기</button></header>'+gameArticle(g)+'</article></div>');document.querySelector('#close-game-news').onclick=closeGameArticle;document.querySelector('#game-news-overlay').onclick=e=>{if(e.target.id==='game-news-overlay')closeGameArticle()};document.addEventListener('keydown',gameNewsEscape);document.querySelectorAll('[data-article-player]').forEach(x=>x.onclick=()=>showPlayer(Number(x.dataset.articlePlayer)))}
function gameNewsEscape(e){if(e.key==='Escape')closeGameArticle()}
function closeGameArticle(){document.querySelector('#game-news-overlay')?.remove();document.removeEventListener('keydown',gameNewsEscape)}
function nextSchedulePanel(){const day=state.day,date=seasonDateLabel(day),pairs=scheduledPairs(day),mine=pairs.find(([a,b])=>a===state.teamId||b===state.teamId);if(!mine){const isMonday=seasonDate(day).getDay()===1,seasonDone=state.teams.every(t=>(t.wins||0)+(t.losses||0)+(t.draws||0)>=144),label=seasonDone?(state.postseasons?.[state.year]?.finished?'한국시리즈 종료 · '+(state.teams[state.postseasons[state.year].champion]?.name||'우승 구단')+' 우승 · '+calendarPhase(seasonDate(day)):calendarPhase(seasonDate(day))+' · 포스트시즌 일정 진행 중'):isMonday?'월요일 정기 휴식일 · 리그 경기 없음':'우리 팀 경기 없음';return '<div class="next-schedule"><strong>'+(isMonday?'휴식일':'다음 일정')+' · '+date+'</strong><div class="schedule-match">'+label+'</div></div>';}const [a,b]=mine,away=state.teams[a],home=state.teams[b],isHome=b===state.teamId;return '<div class="next-schedule"><strong>다음 날 우리 팀 경기 · '+date+'</strong><div class="schedule-match"><b>'+(isHome?'홈 경기':'원정 경기')+'</b> · '+esc(isHome?away.city+' '+away.name:home.city+' '+home.name)+' 상대</div><div class="schedule-match">경기 장소 · '+esc(ballpark(home))+'</div></div>'}
function staffCareerLabel(s){if(!s?.formerPlayerId)return '지도자 · '+(s?.style||'분석형');const p=state.players.find(x=>x.id===s.formerPlayerId),t=state.teams.find(x=>x.id===p?.teamId);return '선수 출신 · '+(p?.position==='P'?'투수':'야수')+' · '+(s.retiredYear||'은퇴')+'년 은퇴'}
function staffRatingsLabel(s,role,teamId){if(role==='감독'){const v=managerRatings(teamId);return '전술 '+v.tactics+' · 투수 '+v.pitching+' · 육성 '+v.development+' · 주루 '+v.baserunning+' · 리더십 '+v.leadership}return '지도 능력 '+(s?.skill||55)+' · '+(s?.style||'분석형')}
function draftResultsDetail(year,picks){const mine=picks.filter(x=>x.teamId===state.teamId),list=[['우리 구단 지명',mine],['전체 구단 지명',picks]];return list.map(([label,rows],i)=>'<details style="margin-top:12px"'+(i===0?' open':'')+'><summary style="font-weight:700;cursor:pointer;padding:10px 0">'+label+' · '+rows.length+'명</summary><div style="overflow-x:auto;-webkit-overflow-scrolling:touch;border:1px solid #e1e8f1;border-radius:10px"><table style="width:100%;min-width:760px;border-collapse:separate;border-spacing:0;font-size:12px;white-space:nowrap;text-align:left"><thead><tr><th style="padding:11px 12px;text-align:left;border-bottom:2px solid #c7d5e6">라운드</th><th style="padding:11px 12px;text-align:left;border-bottom:2px solid #c7d5e6">구단</th><th style="padding:11px 12px;text-align:left;border-bottom:2px solid #c7d5e6">선수</th><th style="padding:11px 12px;text-align:left;border-bottom:2px solid #c7d5e6">포지션</th><th style="padding:11px 12px;text-align:left;border-bottom:2px solid #c7d5e6">출신 학교</th><th style="padding:11px 12px;text-align:right;border-bottom:2px solid #c7d5e6">계약금</th></tr></thead><tbody>'+rows.map(x=>{const p=state.players.find(q=>q.id===x.playerId);if(p)ensurePlayerSchool(p);const t=state.teams.find(q=>q.id===x.teamId);const school=p?[p.highSchool||p.schoolHigh,p.university||p.college].filter(Boolean).join(' → '):x.origin||'-';return '<tr><td style="padding:10px 12px;border-bottom:1px solid #e1e8f1">'+x.round+'R '+x.pick+'순위</td><td style="padding:10px 12px;border-bottom:1px solid #e1e8f1">'+esc(t?.name||'-')+'</td><td style="padding:10px 12px;border-bottom:1px solid #e1e8f1">'+esc(x.name)+'</td><td style="padding:10px 12px;border-bottom:1px solid #e1e8f1">'+esc(x.position||'-')+'</td><td style="padding:10px 12px;border-bottom:1px solid #e1e8f1">'+esc(school)+'</td><td style="padding:10px 12px;border-bottom:1px solid #e1e8f1">'+Math.round((x.signingBonus||0)/10000).toLocaleString()+'만원</td></tr>'}).join('')+'</tbody></table></div></details>').join('')}
function draftHomePanel(){const now=seasonDate(state.day),year=now.getFullYear(),draftYear=year+1,picks=state.draftResults?.[draftYear]||[],mine=picks.filter(x=>x.teamId===state.teamId),date=new Date(year,8,15,12),days=Math.ceil((date-now)/86400000);if(picks.length){const first=mine.find(x=>x.round===1);return '<section class="dashboard-section"><div class="section-title"><div><span class="section-kicker">ROOKIE DRAFT</span><h2>'+draftYear+' 신인 드래프트 완료</h2></div></div><p>10개 구단 '+picks.length+'명 지명 · 우리 구단 '+mine.length+'명 지명</p><p>우리 구단 1라운드 · '+esc(first?.name||'없음')+' ('+esc(first?.position||'-')+')</p><p>지명 선수들은 '+draftYear+'시즌 합류 예정입니다.</p>'+draftResultsDetail(draftYear,picks)+'</section>'}return '<section class="dashboard-section"><div class="section-title"><div><span class="section-kicker">ROOKIE DRAFT</span><h2>'+draftYear+' 신인 드래프트</h2></div></div><p>개최 예정 · '+year+'년 9월 15일'+(days>0?' · D-'+days:days===0?' · 오늘 개최':' · 개최 확인 중')+'</p><p>전년도 성적 역순 · 10개 구단 · 11라운드 자동 지명</p></section>'}
