function batterSkill(p,key){const skills=ensureProfile(p).skills||{};if(Number.isFinite(Number(skills[key])))return Math.max(20,Math.min(99,Number(skills[key])));const o=Number(p.overall)||50,offset=((p.id*131+(key==='speed'?17:key==='power'?41:67))%31)-15;return Math.max(20,Math.min(99,o+offset))}
function batterForm(p,key){const ab=Number(p.atBats)||0,prior=batterSkill(p,key),weight=Math.min(.65,ab/(ab+140));if(!ab)return prior;let observed=prior;if(key==='contact')observed=Math.min(99,Math.max(20,50+((Number(p.hits)||0)/ab-.255)*170));if(key==='power')observed=Math.min(99,Math.max(20,45+((Number(p.homeRuns)||0)/ab-.035)*520));if(key==='speed')observed=Math.min(99,Math.max(20,45+((Number(p.stolenBases)||0)/Math.max(1,Number(p.games)||1)-.12)*100));return prior*(1-weight)+observed*weight}
function managerPhilosophy(manager){
 if(!manager)return '밸런스';
 if(['세이버메트릭스','빅볼','스몰볼','밸런스'].includes(manager.philosophy))return manager.philosophy;
 const styles=['세이버메트릭스','빅볼','스몰볼','밸런스'];
 const seed=String(manager.name||'감독').split('').reduce((n,c)=>n*31+c.charCodeAt(0),17);
 manager.philosophy=styles[(seed>>>0)%styles.length];
 return manager.philosophy;
}
function managerPitchingPhilosophy(manager){
 if(!manager)return '균형형';
 const options=['선발 중시형','불펜 중심형','데이터 분석형','실점 억제형','균형형'];
 if(options.includes(manager.pitchingPhilosophy))return manager.pitchingPhilosophy;
 const seed=String(manager.name||'감독').split('').reduce((n,c)=>n*37+c.charCodeAt(0),29);
 manager.pitchingPhilosophy=options[(seed>>>0)%options.length];
 return manager.pitchingPhilosophy;
}
function clubBattingPhilosophy(club){
 if(club.league==='amateur')return '밸런스';
 const office=officeAI(club.teamId);
 return managerPhilosophy((club.league==='minor'?office.minorManager:office.manager)||office.manager);
}
function clubPitchingPhilosophy(club){
 if(club.league==='amateur')return '균형형';
 const office=officeAI(club.teamId);
 return managerPitchingPhilosophy((club.league==='minor'?office.minorManager:office.manager)||office.manager);
}
function battingOrder(players,style='분석형',philosophy='밸런스'){const remaining=[...players],weights=[['contact',1.25,'speed',1.15,'power',.2],['contact',1.3,'speed',.8,'power',.4],['contact',1.2,'power',1.2,'speed',.25],['power',2,'contact',.55,'speed',0],['power',1.65,'contact',.7,'speed',.15],['power',1.2,'contact',.8,'speed',.2],['contact',.85,'power',.65,'speed',.35],['contact',.8,'speed',.6,'power',.25],['speed',1.15,'contact',.85,'power',.15]];return weights.map(w=>{const rating=p=>{const contact=batterForm(p,'contact'),power=batterForm(p,'power'),speed=batterForm(p,'speed');const base=batterForm(p,w[0])*w[1]+batterForm(p,w[2])*w[3]+batterForm(p,w[4])*w[5];return base+(style==='공격형'?power*.45+speed*.15:style==='안정형'?contact*.5:style==='육성형'?speed*.25+contact*.2:style==='승부형'?power*.55:contact*.25+power*.15)+(philosophy==='빅볼'?power*.6:philosophy==='스몰볼'?contact*.3+speed*.55:philosophy==='세이버메트릭스'?contact*.65+power*.3:0)};remaining.sort((a,b)=>rating(b)-rating(a)||a.id-b.id);return remaining.shift()}).filter(Boolean)}
function defensiveFit(p,slot){if(p.position===slot)return 22;if(p.position==='IF'&&['1B','2B','3B','SS'].includes(slot))return 12;if(p.position==='OF'&&['LF','CF','RF'].includes(slot))return 12;if(['LF','CF','RF'].includes(p.position)&&['LF','CF','RF'].includes(slot))return 7;if(['2B','SS','3B'].includes(p.position)&&['2B','SS','3B'].includes(slot))return 5;return -24}
function chooseBattingNine(players,opponentHand,formScore,style='분석형',philosophy='밸런스'){const slots=['C','SS','2B','3B','1B','CF','LF','RF','DH'],pool=[...players],chosen=[],assigned=new Map();for(const slot of slots){pool.sort((a,b)=>{const val=p=>batterForm(p,'contact')*.45+batterForm(p,'power')*.35+(formScore?formScore(p)*.55:0)+defensiveFit(p,slot)-(Number(playerBaseball(p).fatigue)||0)*.6+(opponentHand&&playerBaseball(p).batHand===(opponentHand==='좌투'?'우타':'좌타')?4:0);return val(b)-val(a)||a.id-b.id});if(pool.length){const eligible=slot==='DH'?pool:pool.filter(p=>defensiveFit(p,slot)>=5);const player=(eligible.length?eligible:pool).sort((a,b)=>{const score=p=>defensiveFit(p,slot)*2+(formScore?formScore(p):p.overall||0)-(playerBaseball(p).fatigue||0)*.3;return score(b)-score(a)||a.id-b.id})[0];pool.splice(pool.indexOf(player),1);chosen.push(player);assigned.set(player.id,slot)}}const ordered=battingOrder(chosen,style,philosophy);ordered.assignedPositions=assigned;return ordered}
function recoverClub(teamId){for(const p of state.players){if(p.teamId!==teamId)continue;const b=playerBaseball(p);b.fatigue=Math.max(0,(Number(b.fatigue)||0)-(Number(b.recovery)||10))}}
