function statNumber(p,keys){for(const k of keys){if(p[k]!==undefined&&p[k]!==null&&Number.isFinite(Number(p[k])))return Number(p[k]);if(p.stats&&p.stats[k]!==undefined&&p.stats[k]!==null&&Number.isFinite(Number(p.stats[k])))return Number(p.stats[k])}return null}
function baseballStatLine(p,role){repairEarlySeasonBatting(p);const get=(...keys)=>statNumber(p,keys),fmt=n=>n===null?'—':String(n),ip=get('inningsPitched'),er=get('earnedRuns'),h=get('hitsAllowed'),bb=get('walksAllowed','basesOnBallsAllowed'),era=ip>0&&er!==null?(er*9/ip).toFixed(2):'—',whip=ip>0&&h!==null&&bb!==null?((h+bb)/ip).toFixed(2):'—',w=fmt(get('pitchingWins','pitcherWins','win')??0),l=fmt(get('pitchingLosses','pitcherLosses','loss')??0),k=fmt(get('pitchingStrikeouts','strikeoutsPitched','strikeouts'));if(p.position==='P'){if(role==='선발'||role==='선발투수')return [['평균자책점',era],['승패',w+'-'+l],['IP',ip===null?'—':baseballIP(Math.round(ip*3))],['탈삼진',k],['이닝당 출루 허용',whip],['QS',fmt(get('qualityStarts','qs'))]];return [['평균자책점',era],['G',fmt(get('games'))],['승패',w+'-'+l],['홀드',fmt(get('holds','hold'))],['세이브',fmt(get('saves','save'))],['블론세이브',fmt(get('blownSaves','blownSave'))],['이닝당 출루 허용',whip],['탈삼진',k]]}const ab=get('atBats'),hits=get('hits'),hr=get('homeRuns'),doubles=get('doubles','twoBaseHits'),triples=get('triples','threeBaseHits'),walks=get('walks','basesOnBalls'),hbp=get('hitByPitch','hitByPitches'),sf=get('sacrificeFlies');const avg=ab>0&&hits!==null?(hits/ab).toFixed(3).replace(/^0/,''):'—';const obp=ab!==null&&hits!==null&&walks!==null&&ab+walks+(hbp??0)+(sf??0)>0?((hits+walks+(hbp??0))/(ab+walks+(hbp??0)+(sf??0))).toFixed(3).replace(/^0/,''):'—';const slg=ab>0&&hits!==null&&doubles!==null&&triples!==null&&hr!==null?((hits+doubles+2*triples+3*hr)/ab).toFixed(3).replace(/^0/,''):'—';const ops=obp!=='—'&&slg!=='—'?(Number(obp)+Number(slg)).toFixed(3).replace(/^0/,''):'—';return [['타율',avg],['홈런',fmt(hr)],['안타',fmt(hits)],['2루타',fmt(doubles)],['3루타',fmt(triples)],['타점',fmt(get('runsBattedIn','rbi','RBIs'))],['도루',fmt(get('stolenBases','steals'))],['실책',fmt(get('fieldingErrors')??0)],['병살타',fmt(get('groundedIntoDoublePlays')??0)],['희생플라이',fmt(get('sacrificeFlies')??0)],['출루율',obp],['장타율',slg],['출루율+장타율',ops]]}
function compactRecord(p,role){return baseballStatLine(p,role).map(([label,value])=>label+' '+value).join(' · ')}
function observerRow(p,label){const isP=p.position==='P',ip=Number(p.inningsPitched)||0,er=Number(p.earnedRuns)||0,era=ip>0?(er*9/ip).toFixed(2):'—',avg=(p.atBats||0)>0?((p.hits||0)/p.atBats).toFixed(3).replace(/^0/,''):'—';const cells=isP?[['승-패',(p.pitchingWins||0)+'-'+(p.pitchingLosses||0)],['ERA',era],['IP',ip>0?baseballIP(Math.round(ip*3)):'—'],...(label==='마무리'?[['SV',p.saves||0]]:[])]:[['AVG',avg],['HR',p.homeRuns||0],['RBI',p.runsBattedIn||0]];return '<div class="observer-row observer-compact" data-player="'+p.id+'" role="button" tabindex="0" aria-label="'+esc(p.name)+' 선수 상세 보기"><span class="observer-name">'+esc(p.name)+'</span><span class="observer-position">'+esc(label)+'</span><span class="observer-metrics">'+cells.map(([k,v])=>'<span class="observer-metric"><small>'+k+'</small><b>'+esc(String(v))+'</b></span>').join('')+'</span></div>'}
