function secondLineupPanel(){const m=minorManagerPlan(state.teamId);const stats=p=>p.minorStats?.seasonYear===state.year?p.minorStats:{};const avg=x=>x.atBats?((x.hits||0)/x.atBats).toFixed(3).replace(/^0/,''):'—';const ops=x=>{if(!x.atBats||!Number.isFinite(x.walks)||!Number.isFinite(x.doubles)||!Number.isFinite(x.triples))return '—';const ab=x.atBats,h=x.hits||0,bb=x.walks||0,hbp=x.hitByPitch||0,sf=x.sacrificeFlies||0,tb=h+(x.doubles||0)+2*(x.triples||0)+3*(x.homeRuns||0);return ((h+bb+hbp)/(ab+bb+hbp+sf||1)+tb/ab).toFixed(3).replace(/^0/,'')};const era=x=>x.innings>0&&Number.isFinite(x.earnedRuns)?(x.earnedRuns*9/x.innings).toFixed(2):'—';const wl=x=>Number.isFinite(x.wins)&&Number.isFinite(x.losses)?x.wins+'-'+x.losses:'—';const row=(p,values,hasOrder)=>'<div class="lineup-grid-row" data-player="'+p.id+'" role="button" tabindex="0" aria-label="'+esc(p.name)+' 선수 상세 보기">'+values.map((v,i)=>'<span class="lineup-grid-cell'+(i===(hasOrder?1:0)?' lineup-grid-name':'')+'">'+esc(String(v))+'</span>').join('')+'</div>';const table=(title,heads,rows)=>'<section class="lineup-section lineup-grid-section"><h3>'+title+'</h3><div class="lineup-grid" style="--lineup-cols:'+heads.length+'"><div class="lineup-grid-head">'+heads.map(h=>'<span>'+h+'</span>').join('')+'</div>'+rows.join('')+'</div></section>';const bat=table('2군 감독 편성 타순 · 1~9번',['순','선수','수비','타율','홈런','안타','OPS'],m.batters.map((p,i)=>{const x=stats(p);return row(p,[i+1,p.name,lineupDisplayPositions(m.batters,m.lineupPositions)[i],avg(x),x.homeRuns||0,x.hits||0,ops(x)],true)}));const rot=table('2군 선발 로테이션',['순','선수','ERA','승패','QS','이닝'],m.rotation.map((p,i)=>{const x=stats(p);return row(p,[i+1,p.name,era(x),wl(x),Number.isFinite(x.qualityStarts)?x.qualityStarts:'—',x.innings?baseballIP(Math.round(x.innings*3)):'—'],true)}));const pen=table('2군 불펜 투수진',['선수','ERA','승패','홀드','세이브'],m.bullpen.map(p=>{const x=stats(p);return row(p,[p.name,era(x),wl(x),Number.isFinite(x.holds)?x.holds:'—',Number.isFinite(x.saves)?x.saves:'—'],false)}));return '<div class="lineup-columns lineup-grid-columns">'+bat+rot+pen+'</div><p class="roster-empty">2군 감독 '+esc(m.manager?.name||'')+'이 자동 편성합니다. 2군 경기 기록만 반영하며, 과거 저장 데이터에 없는 기록은 —로 표시합니다.</p>'}
function lineupDisplayPositions(players,assigned){return players.map(p=>{const slot=assigned?.get(p.id)||p.position;return slot==='DH'?'지명타자':positionName({position:slot},playerBaseball(p))})}
function lineupSquadPanel(){return '<div class="lineup-squad-switch"><button type="button" data-lineup-squad="first" class="'+(lineupSquad==='first'?'active':'')+'">1군 라인업</button><button type="button" data-lineup-squad="second" class="'+(lineupSquad==='second'?'active':'')+'">2군 라인업</button></div>'+(lineupSquad==='second'?secondLineupPanel():lineupPanel())}
function lineupPanel(){const m=autoManager();const bullpenOrder=['필승조','롱릴리프','추격조','패전조','마무리'];const avg=p=>(p.atBats||0)>0?((p.hits||0)/p.atBats).toFixed(3).replace(/^0/,''):'—';const ops=p=>{const ab=p.atBats||0,h=p.hits||0,bb=p.walks||0,hbp=p.hitByPitch||p.hitByPitches||0,sf=p.sacrificeFlies||0,tb=h+(p.doubles||0)+2*(p.triples||0)+3*(p.homeRuns||0);return ab>0?((h+bb+hbp)/(ab+bb+hbp+sf||1)+tb/ab).toFixed(3).replace(/^0/,''):'—'};const era=p=>(p.inningsPitched||0)>0?((p.earnedRuns||0)*9/p.inningsPitched).toFixed(2):'—';const row=(p,cells)=>'<div class="lineup-grid-row" data-player="'+p.id+'" role="button" tabindex="0" aria-label="'+esc(p.name)+' 선수 상세 보기">'+cells.map((v,i)=>'<span class="lineup-grid-cell'+(i===(cells.length===5?0:1)?' lineup-grid-name':'')+'">'+esc(String(v))+'</span>').join('')+'</div>';const table=(title,heads,rows)=>'<section class="lineup-section lineup-grid-section"><h3>'+title+'</h3><div class="lineup-grid" style="--lineup-cols:'+heads.length+'"><div class="lineup-grid-head">'+heads.map(h=>'<span>'+h+'</span>').join('')+'</div>'+rows.join('')+'</div></section>';const bat=table('감독 편성 타순 · 1~9번',['순','선수','수비','타율','홈런','안타','OPS'],m.lineup.map((p,i)=>row(p,[i+1,p.name,lineupDisplayPositions(m.lineup,m.lineupPositions)[i],avg(p),p.homeRuns||0,p.hits||0,ops(p)])));const rot=table('선발 로테이션',['순','선수','ERA','승패','QS','이닝'],m.rotation.map((p,i)=>row(p,[i+1,p.name,era(p),(p.pitchingWins||0)+'-'+(p.pitchingLosses||0),p.qualityStarts||0,p.inningsPitched?baseballIP(Math.round(p.inningsPitched*3)):'—'])));const pen=m.first.filter(p=>p.position==='P'&&!m.rotation.some(x=>x.id===p.id)).sort((a,b)=>bullpenOrder.indexOf(m.roles.get(a.id))-bullpenOrder.indexOf(m.roles.get(b.id))||m.score(b)-m.score(a));const bull=table('불펜 투수진',['선수','ERA','승패','홀드','세이브'],pen.map(p=>row(p,[p.name,era(p),(p.pitchingWins||0)+'-'+(p.pitchingLosses||0),p.holds||0,p.saves||0])));return '<div class="lineup-columns lineup-grid-columns">'+bat+rot+bull+'</div><p class="roster-empty">감독이 자동 편성합니다. 선수를 누르면 상세 기록을 볼 수 있습니다.</p>'}
function pitcherRole(p){if(p.position!=='P')return null;const m=autoManager();return m.roles.get(p.id)||'2군 투수'}
function pitcherRolesPanel(){const m=autoManager(),ps=m.first.filter(p=>p.position==='P');return '<div class="lineup-guide"><strong>투수진 자동 운용</strong><p>감독과 투수코치가 필승조·추격조·패전조·롱릴리프·마무리를 자동 배정합니다. 기록은 간소화된 경기 시뮬레이션을 기준으로 누적됩니다.</p></div><div class="entry-summary"><span>선발 <b>'+m.rotation.length+'</b></span><span>불펜 <b>'+ps.filter(p=>!m.rotation.includes(p)).length+'</b></span><span>마무리 <b>'+ps.filter(p=>m.roles.get(p.id)==='마무리').length+'</b></span></div><section class="entry-group observer-section"><div class="observer-table">'+ps.map(p=>observerRow(p,m.roles.get(p.id)||'불펜')).join('')+'</div></section>'}
function entryPanel(level){const m=autoManager(),team=state.players.filter(p=>p.teamId===state.teamId&&!p.retired&&!['은퇴','방출','계약종료','웨이버 대기','FA대기'].includes(p.level)&&!p.draftPending),first=team.filter(p=>m.chosenIds.has(p.id)),second=team.filter(p=>!m.chosenIds.has(p.id)&&p.level!=='육성'),farm=team.filter(p=>!m.chosenIds.has(p.id)&&p.level==='육성');const summary='<div class="entry-summary"><span>1군 <b>'+first.length+'/28</b></span><span>2군 <b>'+second.length+'</b></span><span>육성 <b>'+farm.length+'</b></span></div>';const sections=level==='first'?[['1군 선수단',first]]:[['2군 선수단',second],['육성 선수',farm]];return '<div class="lineup-guide"><strong>'+(level==='first'?'1군 선수단':'2군 · 육성 선수단')+'</strong><p>감독과 프런트가 선수단을 자동 편성하며 구단주는 명단과 성적만 확인합니다.</p></div>'+summary+rosterResults(sections,sections.reduce((n,x)=>n+x[1].length,0))+'<p class="roster-empty">감독 AI가 경기 출전 선수단을 자동 선정합니다. 선수 명단의 등록 상태와는 구분됩니다.</p>'}
function showRosterPanel(mode){const target=document.querySelector('#roster-workspace');if(!target)return;document.querySelectorAll('[data-roster-mode]').forEach(x=>x.classList.toggle('active',x.dataset.rosterMode===mode));target.innerHTML=mode==='lineup'?lineupSquadPanel():mode==='first'||mode==='second'?entryPanel(mode):rosterBody();bindRosterSearch();document.querySelectorAll('[data-lineup-squad]').forEach(b=>b.onclick=()=>{lineupSquad=b.dataset.lineupSquad;showRosterPanel('lineup')})}
function bindRosterSearch(){const search=document.querySelector('#roster-search'),sort=document.querySelector('#roster-sort');if(search)search.oninput=e=>{rosterQuery=e.target.value;refreshRosterResults()};if(sort)sort.onchange=e=>{rosterSort=e.target.value;refreshRosterResults()};document.querySelectorAll('[data-player]').forEach(row=>{row.onclick=()=>showPlayer(row.dataset.player);row.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();showPlayer(row.dataset.player)}}})}
function foreignManagementPanel(){const players=foreignRoster(state.teamId),changes=state.foreignChanges||{},transactions=Object.entries(changes).filter(([key])=>key.endsWith(':'+state.teamId)).flatMap(([key,v])=>(v.transactions||[]).map(x=>({...x,year:key.split(':')[0]}))).sort((a,b)=>Number(b.year)-Number(a.year)||Number(b.day)-Number(a.day)).slice(0,12);const find=id=>state.players.find(p=>String(p.id)===String(id))?.name||'선수 기록 없음';return '<section class="dashboard-section"><div class="section-title"><div><span class="section-kicker">FOREIGN ROSTER</span><h2>외국인 선수 관리 · '+players.length+'/3명</h2><p>1군·2군·육성군 통합 보유 인원 · 교체는 프런트가 자동 처리</p></div></div><div class="roster-list">'+(players.length?players.map(p=>'<div class="staff-person"><div><strong>'+esc(p.name)+'</strong><small>'+esc(p.position)+' · '+esc(p.level)+' · '+money(Number(p.salary)||0)+' · 계약 '+esc(String(p.foreignContractYear||'미확인'))+'년</small></div></div>').join(''):'<p>계약 중인 외국인 선수가 없습니다.</p>')+'</div><details><summary>외국인 교체 내역 '+transactions.length+'건</summary>'+(transactions.length?transactions.map(x=>'<p>'+esc(String(x.year))+'년 '+esc(String(x.day))+'일 · '+esc(find(x.outId))+' → '+esc(find(x.inId))+' · '+money(Number(x.cost)||0)+'</p>').join(''):'<p>기록된 시즌 중 교체 내역이 없습니다.</p>')+'</details></section>'}
function roster(){return foreignManagementPanel()+'<div class="roster-modes"><button class="active" data-roster-mode="list">선수 명단</button><button data-roster-mode="lineup">타순 · 선발진</button><button data-roster-mode="first">1군</button><button data-roster-mode="second">2군</button></div><div id="roster-workspace">'+rosterBody()+'</div>'}
function rosterBody(){const all=state.players.filter(p=>p.teamId===state.teamId&&!p.retired&&!['은퇴','방출','계약종료','웨이버 대기','FA대기'].includes(p.level));const q=rosterQuery.trim().toLowerCase();const filtered=all.filter(p=>!q||p.name.toLowerCase().includes(q)||String(jerseyNumber(p)).includes(q)||positionName(p,playerBaseball(p)).includes(q));const sorter=(a,b)=>rosterSort==='age'?a.age-b.age||a.id-b.id:rosterSort==='salary'?b.salary-a.salary||a.id-b.id:jerseyNumber(a)-jerseyNumber(b)||a.id-b.id;const sections=[['1군 선수단',filtered.filter(p=>!p.draftPending&&p.level==='1군')],['2군 선수단',filtered.filter(p=>!p.draftPending&&p.level==='2군')],['육성 선수',filtered.filter(p=>!p.draftPending&&p.level!=='1군'&&p.level!=='2군')],['입단 예정 신인',filtered.filter(p=>p.draftPending)]];return '<section class="dashboard-intro"><span class="section-kicker">TEAM ROSTER</span><h2>선수단 <span class="roster-total">'+all.length+'명</span></h2><p>등번호, 선수 이름 또는 포지션으로 검색할 수 있습니다.</p></section><div class="roster-toolbar"><input id="roster-search" type="search" placeholder="이름 · 등번호 · 포지션 검색" value="'+esc(rosterQuery)+'" autocomplete="off" aria-label="선수 검색"><select id="roster-sort" aria-label="선수 정렬"><option value="number"'+(rosterSort==='number'?' selected':'')+'>등번호순</option><option value="age"'+(rosterSort==='age'?' selected':'')+'>나이순</option><option value="salary"'+(rosterSort==='salary'?' selected':'')+'>연봉 높은순</option></select></div><div id="roster-results">'+rosterResults(sections,filtered.length)+'</div>'}
function rosterResults(sections,count){return '<div class="roster-count">검색 결과 '+count+'명</div>'+sections.map(([title,players])=>'<section class="dashboard-section roster-section"><div class="section-title"><div><h2>'+title+'</h2><p>'+players.length+'명</p></div></div><div class="roster-list">'+(players.length?players.sort((a,b)=>rosterSort==='age'?a.age-b.age||a.id-b.id:rosterSort==='salary'?b.salary-a.salary||a.id-b.id:Number(jerseyNumber(a))-Number(jerseyNumber(b))||a.id-b.id).map(p=>'<button class="roster-player player-row" data-player="'+p.id+'" aria-label="'+esc(p.name)+' 상세 보기"><span class="roster-avatar roster-number">'+esc(jerseyNumber(p))+'</span><span class="roster-person"><strong>'+esc(p.name)+'</strong><small>'+esc(positionName(p,playerBaseball(p)))+' · '+p.age+'세</small></span><span class="roster-extra">'+money(p.salary)+'</span><span class="roster-arrow">›</span></button>').join(''):'<p class="roster-empty">해당 선수가 없습니다.</p>')+'</div></section>').join('')}
function refreshRosterResults(){const all=state.players.filter(p=>p.teamId===state.teamId&&!p.retired&&!['은퇴','방출','계약종료','웨이버 대기'].includes(p.level));const q=rosterQuery.trim().toLowerCase();const ps=all.filter(p=>!q||p.name.toLowerCase().includes(q)||String(jerseyNumber(p)).includes(q)||positionName(p,playerBaseball(p)).includes(q));const sections=[['1군 선수단',ps.filter(p=>!p.draftPending&&p.level==='1군')],['2군 선수단',ps.filter(p=>!p.draftPending&&p.level==='2군')],['육성 선수',ps.filter(p=>!p.draftPending&&p.level!=='1군'&&p.level!=='2군')],['입단 예정 신인',ps.filter(p=>p.draftPending)]];const target=document.querySelector('#roster-results');if(!target)return;target.innerHTML=rosterResults(sections,ps.length);target.querySelectorAll('[data-player]').forEach(row=>{row.onclick=()=>showPlayer(row.dataset.player);row.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();showPlayer(row.dataset.player)}}})}
const SKILL_LABELS={contact:'컨택',power:'장타력',eye:'선구안',speed:'주루',fielding:'수비',arm:'송구',control:'제구력',stuff:'구위',stamina:'체력'};
const TRAITS=['성실한 노력형','승부욕이 강한 유형','차분한 분석형','적극적인 도전형','팀워크 중심형','꾸준한 성장형'];
function ensureProfile(p){if(p.profile?.skills)return p.profile;const r=rng((p.id*2654435761)>>>0);const skills={};for(const k of Object.keys(SKILL_LABELS)){const relevant=p.position==='P'?['control','stuff','stamina'].includes(k):!['control','stuff','stamina'].includes(k);skills[k]=Math.max(20,Math.min(99,p.overall+(relevant?6:-8)+ri(r,-19,19)))}p.profile={skills,trait:TRAITS[ri(r,0,TRAITS.length-1)],contractYears:ri(r,1,5),injury:{status:'건강',days:0},growth:[]};return p.profile}
function skillOpinion(k,n){const label=SKILL_LABELS[k];const notes={contact:['정교한 타격에 어려움을 겪을 가능성이 있습니다.','타격 정확도는 평균적인 수준으로 평가됩니다.','공을 배트 중심에 맞히는 능력이 돋보입니다.'],power:['장타보다는 단타 위주의 타격이 예상됩니다.','상황에 따라 장타를 기대할 수 있습니다.','강한 타구를 생산하는 능력이 인상적입니다.'],eye:['유인구 대처와 볼넷 생산에 개선 여지가 있습니다.','볼을 고르는 판단은 무난한 편입니다.','스트라이크존 판단이 안정적이라는 평가입니다.'],speed:['주루에서 적극적인 기여는 제한적일 수 있습니다.','평균적인 주력을 갖췄습니다.','빠른 발을 활용한 주루가 강점입니다.'],fielding:['수비 범위와 안정성에 보완이 필요합니다.','수비에서 무난한 움직임을 보여줄 것으로 보입니다.','타구 판단과 수비 움직임이 좋다는 평가입니다.'],arm:['송구 능력이 약점으로 지적됩니다.','송구 능력은 무난한 편입니다.','강한 어깨가 강점입니다.'],control:['제구 기복이 우려됩니다.','스트라이크존 공략 능력은 무난합니다.','안정적인 제구가 강점으로 평가됩니다.'],stuff:['타자를 압도하는 구위는 부족한 편입니다.','구위는 평균적인 수준으로 보입니다.','타자의 배트를 밀어내는 구위가 돋보입니다.'],stamina:['긴 이닝 소화에는 부담이 예상됩니다.','체력 유지 능력은 무난한 편입니다.','긴 이닝을 소화할 체력을 갖춘 것으로 평가됩니다.']};return notes[k][n>=72?2:n>=50?1:0]}
function playerScouting(p){const x=ensureProfile(p),pitcher=p.position==='P',keys=pitcher?['stuff','control','stamina']:['contact','power','eye','speed','fielding'];const strong=keys.reduce((a,b)=>x.skills[a]>=x.skills[b]?a:b);const weak=keys.reduce((a,b)=>x.skills[a]<=x.skills[b]?a:b);const potential=p.potential>=82?'성장 여력이 크다는 의견이 있지만 실제 성장 여부는 지켜봐야 합니다.':p.potential>=65?'꾸준한 출전 경험에 따라 기량 향상을 기대할 수 있습니다.':'현재의 장점을 살리는 역할이 적합할 것으로 보입니다.';return '<p><strong>강점:</strong> '+esc(skillOpinion(strong,x.skills[strong]))+'</p><p><strong>보완점:</strong> '+esc(skillOpinion(weak,x.skills[weak]))+'</p><p><strong>향후 전망:</strong> '+esc(potential)+'</p>'}
const SCOUTS=[{name:'김도현',focus:'투구 내용과 제구',bias:{control:8,stuff:2,stamina:-3,contact:7,eye:8,power:-5}},{name:'박진우',focus:'구위와 결정구',bias:{stuff:9,control:-4,stamina:1,power:9,contact:-5}},{name:'이성호',focus:'이닝 소화와 안정성',bias:{stamina:8,control:6,stuff:-3,fielding:9,power:-6}}];
function scoutReport(p,s){const x=ensureProfile(p),pitcher=p.position==='P',b=playerBaseball(p),keys=pitcher?['stuff','control','stamina']:['contact','power','eye','speed','fielding'];const ranked=keys.map(k=>({key:k,score:x.skills[k]+(s.bias[k]||0)})).sort((a,b)=>b.score-a.score);const high=ranked[0],low=ranked[ranked.length-1];const focus=pitcher?s.focus:({김도현:'타격과 선구안',박진우:'장타력과 타구 질',이성호:'수비와 주루'}[s.name]||s.focus);const context=pitcher?'제구력·구위·체력·위기 대응 능력을 종합해 평가하며, 선발과 불펜 중 적합한 기용 방식은 감독이 결정합니다.':'타격 생산성과 수비 활용도를 함께 평가하고 있습니다.';return '<article class="scout-note"><h4>'+esc(s.name)+' 스카우트 <span class="muted">· 중점: '+esc(focus)+'</span></h4><p><strong>투수·야수 역할 평가:</strong> '+esc(context)+'</p><p><strong>강점:</strong> '+esc(skillOpinion(high.key,high.score))+'</p><p><strong>보완점:</strong> '+esc(skillOpinion(low.key,low.score))+'</p><p class="muted">실제 관찰 이력은 아직 없습니다. 내부 평가를 바탕으로 한 잠정 의견입니다.</p></article>'}
function performanceOpinion(p){if(p.position==='P'){if((p.inningsPitched||0)<20)return '투구 이닝이 충분하지 않아 실제 성적에 근거한 평가는 보류합니다.';const era=(p.earnedRuns||0)*9/p.inningsPitched;return era<3.5?'현재까지 실점 억제력이 좋은 편입니다.':era<5?'현재까지 평균적인 실점 관리 수준을 보였습니다.':'현재까지 실점 관리에 어려움을 겪었습니다.'}if((p.atBats||0)<60)return '타석 표본이 충분하지 않아 실제 성적에 근거한 평가는 보류합니다.';const avg=(p.hits||0)/p.atBats;return avg>=.3?'현재까지 안타 생산이 꾸준합니다.':avg>=.24?'현재까지 타격 성적은 무난한 편입니다.':'현재까지 안타 생산에 어려움을 겪었습니다.'}
function profileMarkup(p){const x=ensureProfile(p),b=playerBaseball(p);return '<section class="card"><h3>체력 및 출전 관리</h3><p>현재 상태: '+conditionText(p)+'</p><p>'+(p.position==='P'?'투구 이닝과 최근 등판 간격에 따라 피로가 누적되며, 감독이 회복 상태를 고려해 등판을 결정합니다.':'경기 출전량에 따라 피로가 쌓이고 휴식으로 회복됩니다.')+'</p><p class="muted">피로 누적과 회복은 경기 진행 시 반영됩니다.</p></section>'+'<section class="card"><h3>스카우트별 평가</h3><p class="muted">서로 다른 관점을 가진 구단 스카우트의 잠정 평가입니다. 능력치 숫자는 공개하지 않습니다.</p>'+SCOUTS.map(s=>scoutReport(p,s)).join('')+'</section><section class="card"><h3>실제 경기 성적에 따른 평가</h3><p>'+esc(performanceOpinion(p))+'</p><p class="muted">경기 결과가 기록되면 현재 누적 성적을 기준으로 의견이 달라집니다.</p></section><section class="card"><h3>성향 · 계약 · 몸 상태</h3><p>선수 성향: '+esc(x.trait)+'</p><p>계약 잔여 기간: '+x.contractYears+'년</p><p>부상 상태: '+esc(x.injury.status)+'</p></section><section class="card"><h3>성장 기록</h3>'+(x.growth.length?x.growth.map(g=>'<p>'+esc(g.season)+'시즌 · '+esc(g.note)+'</p>').join(''):'<p class="muted">아직 관찰된 성장 기록이 없습니다.</p>')+'</section>'}
function playerBaseball(p){const x=ensureProfile(p);if(!x.baseball){const r=rng((p.id*11939)>>>0);x.baseball={throwHand:r()<.75?'우투':'좌투',batHand:r()<.68?'우타':'좌타',delivery:p.position==='P'?((v)=>v<.64?'오버핸드':v<.92?'쓰리쿼터':v<.985?'사이드암':'언더핸드')(r()):null,role:p.position==='P'?(r()<.48?'선발':'불펜'):null,fatigue:0,recovery:ri(r,8,17),lastAppearance:null}}return x.baseball}
function honorRetiredPlayers(year){
 state.history=state.history||{};const history=state.history;
 history.hallOfFame=history.hallOfFame||[];history.retiredNumbers=history.retiredNumbers||[];
 const seasons=Object.values(history.seasons||{}).filter(x=>Number(x.year)<=Number(year));const playerById=new Map(state.players.map(p=>[String(p.id),p]));
 const records=new Map();
 const summarizedIdsByYear=new Map(seasons.map(season=>[Number(season.year),new Set((season.players||[]).filter(p=>p.id!=null&&(Number(p.games)>0||Number(p.atBats)>0||Number(p.inningsPitched)>0)).map(p=>String(p.id)))]));
 for(const season of seasons)for(const x of season.players||[]){
  if(x.id==null||!(Number(x.games)>0||Number(x.atBats)>0||Number(x.inningsPitched)>0))continue;
  const id=String(x.id),r=records.get(id)||{years:new Set(),byTeam:new Map(),hits:0,homeRuns:0,wins:0,saves:0,strikeouts:0};
  const teamId=String(x.teamId),hasTeamStats=Array.isArray(season.teamPlayerStats),t=hasTeamStats?null:(r.byTeam.get(teamId)||{years:new Set(),hits:0,homeRuns:0,wins:0,saves:0,strikeouts:0});
  r.years.add(Number(season.year));if(t)t.years.add(Number(season.year));
  for(const [field,key] of [['hits','hits'],['homeRuns','homeRuns'],['pitchingWins','wins'],['saves','saves'],['pitchingStrikeouts','strikeouts']]){
   const n=Number(x[field])||0;r[key]+=n;if(t)t[key]+=n;
  }
  if(t)r.byTeam.set(teamId,t);records.set(id,r);
 }
 for(const season of seasons)for(const x of season.teamPlayerStats||[]){
  if(!(Number(x.games)>0))continue;
  const id=String(x.id),r=records.get(id)||{years:new Set(),byTeam:new Map(),hits:0,homeRuns:0,wins:0,saves:0,strikeouts:0};
  r.years.add(Number(season.year));
  const teamId=String(x.teamId),t=r.byTeam.get(teamId)||{years:new Set(),hits:0,homeRuns:0,wins:0,saves:0,strikeouts:0};
  t.years.add(Number(season.year));
  t.hits+=Number(x.hits)||0;t.homeRuns+=Number(x.homeRuns)||0;
  t.wins+=Number(x.pitchingWins)||0;t.saves+=Number(x.saves)||0;t.strikeouts+=Number(x.pitchingStrikeouts)||0;
  r.byTeam.set(teamId,t);
  if(!summarizedIdsByYear.get(Number(season.year))?.has(id)){
   r.hits+=Number(x.hits)||0;r.homeRuns+=Number(x.homeRuns)||0;r.wins+=Number(x.pitchingWins)||0;r.saves+=Number(x.saves)||0;r.strikeouts+=Number(x.pitchingStrikeouts)||0;
  }
  records.set(id,r);
 }
 const awardsByPlayer=new Map();
 for(const [awardYear,list] of Object.entries(state.awards||{})){
  if(Number(awardYear)>Number(year))continue;
  for(const award of list||[]){
   const id=String(award.playerId),arr=awardsByPlayer.get(id)||[];
   arr.push(award);awardsByPlayer.set(id,arr);
  }
 }
 const champions=new Set(Object.values(state.postseasons||{}).filter(x=>x?.finished&&x.champion!=null&&Number(x.year)<=Number(year)).map(x=>String(x.year)+':'+String(x.champion)));
 const honorScore=(r,playerId,teamId=null)=>{
  const stats=teamId==null?r:r.byTeam.get(String(teamId));
  if(!stats)return 0;
  const years=stats.years.size;
  const performance=playerById.get(String(playerId))?.position==='P'
   ?Math.min(65,stats.wins*.19+stats.saves*.105+stats.strikeouts*.012)
   :Math.min(65,stats.hits*.023+stats.homeRuns*.085);
  const awards=(awardsByPlayer.get(String(playerId))||[]).filter(a=>teamId==null||String(a.teamId)===String(teamId));
  let awardPoints=0;
  for(const a of awards){
   const title=String(a.title||'');
   awardPoints+=/MVP|최우수선수/.test(title)?12:/골든글러브/.test(title)?5:/신인왕/.test(title)?4:2;
  }
  const championships=teamId==null?0:[...stats.years].filter(y=>champions.has(String(y)+':'+String(teamId))).length;
  return performance+Math.min(24,awardPoints)+Math.min(12,years*.7)+Math.min(12,championships*4);
 };
 const existingHall=new Set(history.hallOfFame.map(x=>String(x.playerId??x.id)));
 const existingNumbers=new Set(history.retiredNumbers.map(x=>String(x.teamId)+':'+String(x.number)));
 const existingHonoredPlayers=new Set(history.retiredNumbers.map(x=>String(x.teamId)+':'+String(x.playerId??x.id)));
 const eligibleRetirees=(state.retiredPlayers||[]).filter(x=>Number(x.year)<=Number(year));
 for(const retired of eligibleRetirees){
  const id=String(retired.id),p=playerById.get(id),r=records.get(id);
  if(!p||!r)continue;
  const hallEligible=r.years.size>=10&&honorScore(r,id)>=72;
  if(hallEligible&&!existingHall.has(id)){
   history.hallOfFame.push({playerId:p.id,name:p.name,year,inductedYear:year});
   existingHall.add(id);
  }
  for(const [teamId,t] of r.byTeam){
   const qualified=t.years.size>=8&&honorScore(r,id,teamId)>=80;
   if(!qualified)continue;
   const number=Number(retired.teamId)===Number(teamId)&&retired.jerseyNumber!=null?Number(retired.jerseyNumber):NaN;
   if(!Number.isInteger(number)||number<0||number>999||existingNumbers.has(teamId+':'+number)||existingHonoredPlayers.has(teamId+':'+id))continue;
   history.retiredNumbers.push({playerId:p.id,name:p.name,teamId:Number(teamId),number,year});
   existingNumbers.add(teamId+':'+number);
   existingHonoredPlayers.add(teamId+':'+id);
   for(const active of state.players){if(String(active.teamId)===teamId&&String(active.id)!==id&&!active.retired&&!['방출','은퇴','계약종료'].includes(active.level)&&Number(active.jerseyNumber)===number)active.jerseyNumber=null;}
  }
 }
}
function jerseyNumber(p){
 if(!state?.players)return p.jerseyNumber??'—';
 const teamId=p.teamId;
 const roster=state.players.filter(x=>String(x.teamId)===String(teamId)&&!x.retired&&!['방출','은퇴','계약종료'].includes(x.level)).sort((a,b)=>{
  const priority=x=>x.level==='1군'?0:x.level==='2군'?1:x.level==='육성'?2:3;
  return priority(a)-priority(b)||Number(a.id)-Number(b.id);
 });
 const reserved=new Set((state.history?.retiredNumbers||[]).filter(x=>String(x.teamId)===String(teamId)).map(x=>Number(x.number)).filter(n=>Number.isInteger(n)&&n>=0));
 const used=new Set(reserved);
 // Preserve each player's valid existing number when possible.
 for(const x of roster){
  const n=Number(x.jerseyNumber);
  if(x.jerseyNumber!=null&&Number.isInteger(n)&&n>=0&&!used.has(n))used.add(n);
  else x.jerseyNumber=null;
 }
 // Prefer 1–99, then allocate 100+ if the club has no free two-digit numbers.
 for(const x of roster){
  if(x.jerseyNumber!=null)continue;
  let n=1;
  while(n<=99&&used.has(n))n++;
  if(n>99){n=100;while(used.has(n))n++}
  x.jerseyNumber=n;used.add(n);
 }
 return p.jerseyNumber??'—';
}
function positionName(p,b){return p.position==='P'?'투수':({C:'포수','1B':'1루수','2B':'2루수','3B':'3루수',SS:'유격수',LF:'좌익수',CF:'중견수',RF:'우익수',IF:'내야수',OF:'외야수'}[p.position]||p.position)}
function playerFace(p){if(p.profile?.photoData&&/^data:image\/(jpeg|png|webp);base64,/.test(p.profile.photoData))return '<img class="real-player-photo" src="'+p.profile.photoData+'" alt="'+esc(p.name)+' 선수 프로필 사진">';const team=state.teams.find(t=>t.id===p.teamId);const initials=esc(team?.name||'BE');const num=String(jerseyNumber(p));return '<div class="official-player-art" role="img" aria-label="선수 사진 미등록 · 구단 유니폼 대체 이미지"><div class="jersey-halo"></div><div class="jersey-shoulders"><div class="jersey-body"><span class="jersey-letters">'+initials+'</span><span class="jersey-number">'+num+'</span></div></div><span class="jersey-photo-status">선수 사진 미등록</span></div>'}

function conditionText(p){const b=playerBaseball(p);return b.fatigue>=80?'휴식 필요':b.fatigue>=55?'피로 누적':b.fatigue>=30?'관리 필요':'정상'}
function hasPlayedFirstTeamSeason(x){return (Number(x?.games)||0)>0||(Number(x?.atBats)||0)>0||(Number(x?.inningsPitched)||0)>0}
function careerSeasonRows(p){const stored=state.careerRecords?.[p.id]||[];const current=Number(state.year||new Date().getFullYear());const firstYear=Number(p.joinYear||p.draftYear||0);const byYear=new Map();for(const row of stored){const year=Number(row.year);if(year>=firstYear&&hasPlayedFirstTeamSeason(row))byYear.set(year,{...row,year})}if(current>=firstYear){const stats=currentSeasonBoxStats(p);if(hasPlayedFirstTeamSeason(stats))byYear.set(current,{year:current,teamId:p.teamId,games:stats.games||0,atBats:stats.atBats||0,hits:stats.hits||0,doubles:stats.doubles||0,triples:stats.triples||0,homeRuns:stats.homeRuns||0,runsBattedIn:stats.runsBattedIn||0,runs:stats.runs||0,stolenBases:stats.stolenBases||0,inningsPitched:stats.inningsPitched||0,earnedRuns:stats.earnedRuns||0,pitchingWins:stats.pitchingWins||0,pitchingLosses:stats.pitchingLosses||0,saves:stats.saves||0,holds:stats.holds||0})}return [...byYear.values()].sort((a,b)=>b.year-a.year)}
function careerTable(p){const pitcher=p.position==='P',rows=careerSeasonRows(p);const currentYear=Number(state.year),playedClubs=new Set();for(const g of state.gameResults||[]){if(g.year!=null&&Number(g.year)!==currentYear)continue;if(p.draftPending||currentYear<Number(p.firstEligibleYear||p.joinYear||0)||(currentYear===Number(p.firstEligibleYear||p.joinYear||0)&&Number(g.day||0)<Number(p.firstEligibleDay||1)))continue;for(const side of ['away','home'])if(((pitcher?g[side+'Pitchers']:g[side+'Batters'])||[]).some(x=>String(x.id)===String(p.id)&&(!x.name||x.name===p.name)))playedClubs.add(g[side])}const currentClubLabel=[...playedClubs].map(id=>state.teams.find(t=>String(t.id)===String(id))?.name||'이전 구단').join(' / ');const cols=pitcher?['연도','구단','등판','이닝','평균자책점','승','패','홀드','세이브']:['연도','구단','경기','타수','안타','타율','2루타','3루타','홈런','타점','도루'];const perClub=new Map();for(const g of state.gameResults||[]){if(g.year!=null&&Number(g.year)!==currentYear)continue;if(p.draftPending||currentYear<Number(p.firstEligibleYear||p.joinYear||0)||(currentYear===Number(p.firstEligibleYear||p.joinYear||0)&&Number(g.day||0)<Number(p.firstEligibleDay||1)))continue;for(const side of ['away','home']){const lines=((pitcher?g[side+'Pitchers']:g[side+'Batters'])||[]).filter(x=>String(x.id)===String(p.id)&&(!x.name||x.name===p.name));if(!lines.length)continue;const id=String(g[side]);if(!perClub.has(id))perClub.set(id,{teamId:g[side],games:0,atBats:0,hits:0,doubles:0,triples:0,homeRuns:0,runsBattedIn:0,stolenBases:0,inningsPitched:0,earnedRuns:0,pitchingWins:0,pitchingLosses:0,holds:0,saves:0});const a=perClub.get(id);a.games++;for(const line of lines){for(const k of ['atBats','hits','doubles','triples','homeRuns','runsBattedIn','stolenBases','earnedRuns'])a[k]+=Number(line[k])||0;a.inningsPitched+=Number(line.innings)||0;for(const [dest,flag] of [['pitchingWins','win'],['pitchingLosses','loss'],['holds','hold'],['saves','save']])if(line[flag])a[dest]++}}}const tableRows=rows.flatMap(x=>{const team=state.teams.find(t=>t.id===x.teamId);const nums=pitcher?[x.games||0,baseballIP(Math.round(Number(x.inningsPitched||0)*3)),x.inningsPitched>0?((x.earnedRuns||0)*9/x.inningsPitched).toFixed(2):'—',x.pitchingWins||0,x.pitchingLosses||0,x.holds||0,x.saves||0]:[x.games||0,x.atBats||0,x.hits||0,x.atBats?((x.hits||0)/x.atBats).toFixed(3).replace(/^0/,''): '—',x.doubles??'—',x.triples??'—',x.homeRuns||0,x.runsBattedIn||0,x.stolenBases||0];const total='<tr><th>'+x.year+'</th><td>'+esc(Number(x.year)===currentYear&&perClub.size>1?'시즌 합계':(Number(x.year)===currentYear&&currentClubLabel?currentClubLabel:(team?.name||'이전 구단')))+'</td>'+nums.map(n=>'<td>'+n+'</td>').join('')+'</tr>';if(Number(x.year)!==currentYear||perClub.size<2)return [total];const clubs=[...perClub.values()].map(v=>{const name=state.teams.find(t=>String(t.id)===String(v.teamId))?.name||'이전 구단';const n=pitcher?[v.games,baseballIP(Math.round(v.inningsPitched*3)),v.inningsPitched?(v.earnedRuns*9/v.inningsPitched).toFixed(2):'—',v.pitchingWins,v.pitchingLosses,v.holds,v.saves]:[v.games,v.atBats,v.hits,v.atBats?(v.hits/v.atBats).toFixed(3).replace(/^0/,''):'—',v.doubles,v.triples,v.homeRuns,v.runsBattedIn,v.stolenBases];return '<tr><th>'+x.year+'</th><td>'+esc(name)+'</td>'+n.map(value=>'<td>'+value+'</td>').join('')+'</tr>'});return [...clubs,total]}).join('');return '<h3 class="profile-heading">연도별 통산 기록</h3><p class="profile-note">실제 게임에서 저장된 시즌만 표시됩니다. 기록이 없는 과거 시즌은 생성하지 않습니다.</p><div class="scoreboard-scroll career-scroll"><table class="scoreboard-table career-stats"><thead><tr>'+cols.map(c=>'<th>'+c+'</th>').join('')+'</tr></thead><tbody>'+tableRows+'</tbody></table></div><p class="profile-note">데뷔부터 은퇴까지 시즌 종료 시 기록이 누적되는 선수 경력표입니다. 현재는 진행 중인 시즌 기록이 표시됩니다.</p>'}
function pitcherType(p){const a=pitchingArsenal(p),sk=ensureProfile(p).skills||{};const v=a.velocity;return v>=149?'강속구형':v>=144&&Number(sk.stuff||0)>=65?'파워피처형':Number(sk.control||0)>=Number(sk.stuff||0)+9?'제구형':a.pitches.length>=4?'변화구형':v<=137?'기교파형':'균형형'}
function pitcherPitchSpeed(p,name){const v=pitchingArsenal(p).velocity;const diff={'직구':0,'포심 패스트볼':0,'투심':-4,'커터':-5,'슬라이더':-10,'커브':-22,'체인지업':-14,'포크':-13,'스플리터':-12,'싱커':-5};return Math.max(95,v+(diff[name]??-12))}
