function goldPositionEligible(p,pos){if(pos==='투수')return p.position==='P';if(p.position==='P')return false;const counts=playerPositionAppearances(p.id),total=Object.values(counts).reduce((n,x)=>n+x,0);if(!total)return false;const n=pos==='외야수'?(counts.LF||0)+(counts.CF||0)+(counts.RF||0):pos==='지명타자'?(counts.DH||0):counts[({'포수':'C','1루수':'1B','2루수':'2B','3루수':'3B','유격수':'SS'}[pos])]||0;return n>=Math.max(1,Math.ceil(total*.5))}
