    const player=playerById.get(String(line.id));if(!player||(line.name&&line.name!==player.name)||player.draftPending||Number(year)<Number(player.firstEligibleYear||player.joinYear||0)||(Number(year)===Number(player.firstEligibleYear||player.joinYear||0)&&Number(g.day||0)<Number(player.firstEligibleDay||1)))continue;
