(async()=>{try{db=await openDB();state=await load();if(state&&state.schema!==1){app.innerHTML='<main class="wrap"><h2>지원되지 않는 저장 버전</h2><p>데이터 보호를 위해 자동 초기화하지 않았습니다.</p></main>';return}entryMode='title';render()}catch(e){app.innerHTML='<main class="wrap"><h2 class="error">저장소 초기화 실패</h2><p>'+esc(e.message)+'</p></main>'}})();